def parse_serialized_list(
    value: Any,
) -> List[str]:
    """
    Convert a list, tuple, JSON string, Python-style list string,
    scalar, or missing value into a clean list of strings.
    """

    if value is None:

        return []

    if isinstance(
        value,
        (
            list,
            tuple,
            set,
            np.ndarray,
            pd.Series,
        ),
    ):

        return [
            str(
                item
            ).strip()
            for item in value
            if str(
                item
            ).strip()
        ]

    try:

        if pd.isna(
            value
        ):

            return []

    except (
        TypeError,
        ValueError,
    ):

        pass

    value_text = str(
        value
    ).strip()

    if not value_text:

        return []

    try:

        parsed_value = json.loads(
            value_text
        )

        if isinstance(
            parsed_value,
            list,
        ):

            return [
                str(
                    item
                ).strip()
                for item in parsed_value
                if str(
                    item
                ).strip()
            ]

    except (
        json.JSONDecodeError,
        TypeError,
    ):

        pass

    cleaned_text = (
        value_text
        .strip(
            "[]"
        )
        .strip()
    )

    if not cleaned_text:

        return []

    return [
        item.strip().strip(
            "'\""
        )
        for item in cleaned_text.split(
            ","
        )
        if item.strip().strip(
            "'\""
        )
    ]


def normalize_winner_label(
    value: Any,
) -> str:
    """
    Normalize a winner value to Player, Opponent, or Draw.
    """

    if value is None:

        return "Draw"

    try:

        if pd.isna(
            value
        ):

            return "Draw"

    except (
        TypeError,
        ValueError,
    ):

        pass

    value_text = str(
        value
    ).strip()

    value_lower = value_text.lower()

    if value_lower == "player":

        return "Player"

    if value_lower == "opponent":

        return "Opponent"

    if value_lower in {
        "",
        "none",
        "nan",
        "draw",
        "tie",
    }:

        return "Draw"

    return value_text


def resolve_column_name(
    dataframe: pd.DataFrame,
    candidates: Sequence[str],
    required: bool = True,
) -> Optional[str]:
    """
    Return the first available candidate column.
    """

    for column_name in candidates:

        if column_name in dataframe.columns:

            return column_name

    if required:

        raise KeyError(
            "Required column was not found. Candidates: "
            f"{list(candidates)}"
        )

    return None


