# 17. Determine principal optimization opportunity
# --------------------------------------------------------------------------------------

loss_opportunities_df = strategic_opportunity_df.loc[
    strategic_opportunity_df[
        "player_loss_flag"
    ].eq(
        1
    )
].copy()


if not loss_opportunities_df.empty:

    principal_opportunity_condition = str(
        loss_opportunities_df[
            "condition_id"
        ].value_counts().index[
            0
        ]
    )

    principal_opportunity_card = str(
        loss_opportunities_df[
            "active_card"
        ].value_counts().index[
            0
        ]
    )

    principal_opportunity_move = str(
        loss_opportunities_df[
            "selected_move"
        ].value_counts().index[
            0
        ]
    )

else:

    principal_opportunity_condition = (
        "NONE"
    )

    principal_opportunity_card = (
        "NONE"
    )

    principal_opportunity_move = (
        "NONE"
    )


# --------------------------------------------------------------------------------------
# 18. Validation checks
# --------------------------------------------------------------------------------------

section2a_validation_rows = []


def add_section2a_check(
    check_name: str,
    passed: bool,
    value: Any,
    expected: Any,
    details: str = "",
) -> None:

    section2a_validation_rows.append(
        {
            "check":
                check_name,

            "passed":
                bool(
                    passed
                ),

            "value":
                value,

            "expected":
                expected,

            "details":
                details,
        }
    )


add_section2a_check(
    "decision_count_valid",
    len(
        decision_analysis_df
    ) == 210,
    len(
        decision_analysis_df
    ),
    210,
)

add_section2a_check(
    "single_action_count_valid",
    int(
        decision_analysis_df[
            "action_state_type"
        ].eq(
            "SINGLE_ACTION"
        ).sum()
    ) == 187,
    int(
        decision_analysis_df[
            "action_state_type"
        ].eq(
            "SINGLE_ACTION"
        ).sum()
    ),
    187,
)

add_section2a_check(
    "multi_action_count_valid",
    len(
        strategic_opportunity_df
    ) == 23,
    len(
        strategic_opportunity_df
    ),
    23,
)

add_section2a_check(
    "decision_outcomes_complete",
    decision_analysis_df[
        "player_outcome"
    ].isin(
        [
            "WIN",
            "LOSS",
            "DRAW",
        ]
    ).all(),
    sorted(
        decision_analysis_df[
            "player_outcome"
        ].unique().tolist()
    ),
    [
        "DRAW",
        "LOSS",
        "WIN",
    ],
)

add_section2a_check(
    "legal_move_counts_positive",
    decision_analysis_df[
        "legal_move_count"
    ].gt(
        0
    ).all(),
    int(
        decision_analysis_df[
            "legal_move_count"
        ].min()
    ),
    "> 0",
)

add_section2a_check(
    "multi_action_counts_greater_than_one",
    strategic_opportunity_df[
        "legal_move_count"
    ].gt(
        1
    ).all(),
    int(
        strategic_opportunity_df[
            "legal_move_count"
        ].min()
    ),
    "> 1",
)

add_section2a_check(
    "confidence_values_valid",
    strategic_opportunity_df[
        "confidence"
    ].between(
        0.0,
        1.0,
        inclusive="both",
    ).all(),
    {
        "minimum":
            float(
                strategic_opportunity_df[
                    "confidence"
                ].min()
            ),

        "maximum":
            float(
                strategic_opportunity_df[
                    "confidence"
                ].max()
            ),
    },
    "Between 0 and 1",
)

add_section2a_check(
    "scenario_context_complete",
    strategic_opportunity_df[
        "player_card"
    ].notna().all()
    and strategic_opportunity_df[
        "opponent_card"
    ].notna().all(),
    int(
        strategic_opportunity_df[
            [
                "player_card",
                "opponent_card",
            ]
        ].isna().sum().sum()
    ),
    0,
)

add_section2a_check(
    "priority_scores_finite",
    np.isfinite(
        strategic_opportunity_df[
            "priority_score"
        ].to_numpy(
            dtype=float
        )
    ).all(),
    int(
        np.isfinite(
            strategic_opportunity_df[
                "priority_score"
            ].to_numpy(
                dtype=float
            )
        ).sum()
    ),
    len(
        strategic_opportunity_df
    ),
)

add_section2a_check(
    "frozen_replay_unchanged",
    len(
        notebook53_replay_battles_df
    ) == 24
    and len(
        notebook53_policy_history_df
    ) == 210,
    {
        "battles":
            len(
                notebook53_replay_battles_df
            ),

        "decisions":
            len(
                notebook53_policy_history_df
            ),
    },
    {
        "battles":
            24,

        "decisions":
            210,
    },
)


section2a_validation_checks_df = pd.DataFrame(
    section2a_validation_rows
)


print()
print("STRATEGIC OPPORTUNITY VALIDATION CHECKS")
print("-" * 100)

display(
    section2a_validation_checks_df
)


section2a_checks_passed = int(
    section2a_validation_checks_df[
        "passed"
    ].astype(bool).sum()
)

section2a_checks_failed = int(
    (
        ~section2a_validation_checks_df[
            "passed"
        ].astype(bool)
    ).sum()
)


assert section2a_checks_failed == 0, (
    "One or more strategic opportunity analysis checks failed."
)


