supported_structured_suffixes = {
    ".csv",
    ".json",
    ".jsonl",
    ".parquet",
    ".feather",
    ".pkl",
    ".pickle",
}


excluded_directory_names = {
    ".git",
    ".ipynb_checkpoints",
    "__pycache__",
    ".venv",
    "venv",
    "env",
    "node_modules",
}


def path_is_excluded(
    file_path: Path,
) -> bool:
    """
    Return True when a path belongs to an excluded directory.
    """

    return any(
        path_part in excluded_directory_names
        for path_part in file_path.parts
    )


structured_file_rows = []

for file_path in PROJECT_ROOT.rglob(
    "*"
):

    if not file_path.is_file():

        continue

    if path_is_excluded(
        file_path
    ):

        continue

    if file_path.suffix.lower() not in supported_structured_suffixes:

        continue

    file_name_lower = file_path.name.lower()

    relevance_keywords = [
        "card",
        "move",
        "attack",
        "pokemon",
        "deck",
        "battle",
        "metadata",
        "reference",
    ]

    keyword_hits = [
        keyword
        for keyword in relevance_keywords
        if keyword in file_name_lower
    ]

    structured_file_rows.append(
        {
            "path":
                str(
                    file_path
                ),

            "file_name":
                file_path.name,

            "suffix":
                file_path.suffix.lower(),

            "size_bytes":
                int(
                    file_path.stat().st_size
                ),

            "keyword_hits":
                keyword_hits,

            "relevance_score":
                int(
                    len(
                        keyword_hits
                    )
                ),
        }
    )


