# --------------------------------------------------------------------------------------
# 5. Safe structured-file loading
# --------------------------------------------------------------------------------------

def load_structured_dataframe(
    file_path: Path,
) -> Optional[pd.DataFrame]:
    """
    Safely load a supported structured file as a DataFrame.
    """

    suffix = file_path.suffix.lower()

    try:

        if suffix == ".csv":

            return pd.read_csv(
                file_path,
                low_memory=False,
            )

        if suffix == ".json":

            try:

                return pd.read_json(
                    file_path
                )

            except ValueError:

                with open(
                    file_path,
                    "r",
                    encoding="utf-8",
                ) as file:

                    json_value = json.load(
                        file
                    )

                if isinstance(
                    json_value,
                    list,
                ):

                    return pd.DataFrame(
                        json_value
                    )

                if isinstance(
                    json_value,
                    dict,
                ):

                    for value in json_value.values():

                        if isinstance(
                            value,
                            list,
                        ):

                            return pd.DataFrame(
                                value
                            )

                    return pd.DataFrame(
                        [
                            json_value
                        ]
                    )

        if suffix == ".jsonl":

            return pd.read_json(
                file_path,
                lines=True,
            )

        if suffix == ".parquet":

            return pd.read_parquet(
                file_path
            )

        if suffix == ".feather":

            return pd.read_feather(
                file_path
            )

        if suffix in {
            ".pkl",
            ".pickle",
        }:

            loaded_value = pd.read_pickle(
                file_path
            )

            if isinstance(
                loaded_value,
                pd.DataFrame,
            ):

                return loaded_value

            if isinstance(
                loaded_value,
                list,
            ):

                return pd.DataFrame(
                    loaded_value
                )

    except Exception:

        return None

    return None


