# --------------------------------------------------------------------------------------
# 9. Extract class fields and function signatures from simulator source
# --------------------------------------------------------------------------------------

source_symbol_rows = []


for module_name, source_text in (
    simulator_source_text.items()
):

    syntax_tree = ast.parse(
        source_text
    )

    for node in syntax_tree.body:

        if isinstance(
            node,
            ast.ClassDef,
        ):

            class_fields = []

            for child_node in ast.walk(
                node
            ):

                if isinstance(
                    child_node,
                    ast.AnnAssign,
                ) and isinstance(
                    child_node.target,
                    ast.Name,
                ):

                    class_fields.append(
                        child_node.target.id
                    )

            source_symbol_rows.append(
                {
                    "module_name":
                        module_name,

                    "symbol_type":
                        "class",

                    "symbol_name":
                        node.name,

                    "arguments":
                        [],

                    "fields":
                        sorted(
                            set(
                                class_fields
                            )
                        ),
                }
            )

        elif isinstance(
            node,
            ast.FunctionDef,
        ):

            source_symbol_rows.append(
                {
                    "module_name":
                        module_name,

                    "symbol_type":
                        "function",

                    "symbol_name":
                        node.name,

                    "arguments":
                        [
                            argument.arg
                            for argument in node.args.args
                        ],

                    "fields":
                        [],
                }
            )


section3b_source_symbols_df = pd.DataFrame(
    source_symbol_rows
)


print()
print("SIMULATOR SOURCE SYMBOLS")
print("-" * 100)

display(
    section3b_source_symbols_df
)


