# --------------------------------------------------------------------------------------
# 3. Text normalization helpers
# --------------------------------------------------------------------------------------

def normalize_card_name(
    value: Any,
) -> str:
    """
    Normalize a card name for exact tournament-card matching.
    """

    if value is None:

        return ""

    try:

        if pd.isna(
            value
        ):

            return ""

    except (
        TypeError,
        ValueError,
    ):

        pass

    value_text = str(
        value
    ).strip()

    value_text = re.sub(
        r"\s+",
        " ",
        value_text,
    )

    return value_text


def normalize_move_name(
    value: Any,
) -> str:
    """
    Normalize a move name while preserving readable capitalization.
    """

    if value is None:

        return ""

    try:

        if pd.isna(
            value
        ):

            return ""

    except (
        TypeError,
        ValueError,
    ):

        pass

    value_text = str(
        value
    ).strip()

    value_text = re.sub(
        r"\s+",
        " ",
        value_text,
    )

    value_text = value_text.strip(
        "\"'"
    )

    return value_text


def parse_damage_value(
    value: Any,
) -> Optional[float]:
    """
    Parse direct numeric damage.

    Values such as '20+', '30×', or blank text are not treated as
    directly supported fixed damage unless a single numeric value can
    be safely resolved.
    """

    if value is None:

        return None

    try:

        if pd.isna(
            value
        ):

            return None

    except (
        TypeError,
        ValueError,
    ):

        pass

    if isinstance(
        value,
        (
            int,
            float,
            np.integer,
            np.floating,
        ),
    ):

        parsed_value = float(
            value
        )

        if np.isfinite(
            parsed_value
        ) and parsed_value >= 0:

            return parsed_value

        return None

    value_text = str(
        value
    ).strip()

    if not value_text:

        return None

    if value_text.lower() in {
        "nan",
        "none",
        "null",
        "n/a",
    }:

        return None

    # Direct fixed-number value.
    direct_match = re.fullmatch(
        r"\d+(?:\.\d+)?",
        value_text,
    )

    if direct_match:

        parsed_value = float(
            value_text
        )

        return (
            parsed_value
            if parsed_value >= 0
            else None
        )

    return None


def source_path_priority(
    source_path: str,
) -> int:
    """
    Assign a conservative source priority.

    Raw/reference/data sources rank above generated reports and models.
    """

    path_text = str(
        source_path
    ).lower()

    priority = 0

    trusted_tokens = [
        "\\data\\",
        "\\dataset\\",
        "\\datasets\\",
        "\\input\\",
        "\\inputs\\",
        "\\reference\\",
        "\\references\\",
        "\\resources\\",
    ]

    generated_tokens = [
        "\\reports\\",
        "\\models\\",
        "\\scripts\\",
        "\\notebooks\\",
    ]

    if any(
        token in path_text
        for token in trusted_tokens
    ):

        priority += 10

    if any(
        token in path_text
        for token in generated_tokens
    ):

        priority -= 5

    if "card" in Path(
        source_path
    ).name.lower():

        priority += 3

    if "metadata" in Path(
        source_path
    ).name.lower():

        priority += 3

    return priority


