def prepare_section4a_export(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """
    JSON-encode nested cells for CSV export.
    """

    export_df = dataframe.copy()

    for column_name in export_df.columns:

        nested_mask = export_df[
            column_name
        ].apply(
            lambda value: isinstance(
                value,
                (
                    list,
                    tuple,
                    set,
                    dict,
                ),
            )
        )

        if nested_mask.any():

            export_df[
                column_name
            ] = export_df[
                column_name
            ].apply(
                lambda value: json.dumps(
                    (
                        list(
                            value
                        )
                        if isinstance(
                            value,
                            set,
                        )
                        else value
                    ),
                    ensure_ascii=False,
                )
                if isinstance(
                    value,
                    (
                        list,
                        tuple,
                        set,
                        dict,
                    ),
                )
                else value
            )

    return export_df


