# --------------------------------------------------------------------------------------
# 5. Card HP profile for isolated tests
# --------------------------------------------------------------------------------------

ISOLATED_TEST_HP = {
    "Bulbasaur":
        200.0,

    "Charmander":
        200.0,

    "Eevee":
        200.0,

    "Meowth":
        200.0,
}


DUMMY_OPPONENT_HP = 500.0


# --------------------------------------------------------------------------------------
# 6. Construct one isolated candidate test state
# --------------------------------------------------------------------------------------

def build_candidate_transition_state(
    card_name: str,
    move_name: str,
    damage: float,
) -> Any:
    """
    Build a controlled state in which the candidate move is the only move.
    """

    candidate_card = {
        "name":
            str(
                card_name
            ),

        "hp":
            float(
                ISOLATED_TEST_HP.get(
                    card_name,
                    200.0,
                )
            ),

        "moves": [
            {
                "name":
                    str(
                        move_name
                    ),

                "damage":
                    float(
                        damage
                    ),
            }
        ],
    }

    dummy_card = {
        "name":
            "Transition Test Dummy",

        "hp":
            float(
                DUMMY_OPPONENT_HP
            ),

        "moves": [
            {
                "name":
                    "Pass",

                "damage":
                    0.0,
            }
        ],
    }

    player_pokemon = PokemonState54(
        card=candidate_card,
        current_hp=float(
            candidate_card[
                "hp"
            ]
        ),
        attached_energy=0,
        damage=0.0,
        is_active=True,
    )

    opponent_pokemon = PokemonState54(
        card=dummy_card,
        current_hp=float(
            dummy_card[
                "hp"
            ]
        ),
        attached_energy=0,
        damage=0.0,
        is_active=True,
    )

    player_state = PlayerState54(
        active=player_pokemon,
        bench=[],
        prize_cards_remaining=6,
        hand_size=7,
    )

    opponent_state = PlayerState54(
        active=opponent_pokemon,
        bench=[],
        prize_cards_remaining=6,
        hand_size=7,
    )

    return BattleState54(
        player=player_state,
        opponent=opponent_state,
        turn_number=1,
        current_player="Player",
    )


# --------------------------------------------------------------------------------------
# 7. Test every additional source-backed move
# --------------------------------------------------------------------------------------

candidate_transition_rows = []


for candidate_index, candidate_row in (
    section4a_additional_candidates_df
    .reset_index(
        drop=True
    )
    .iterrows()
):

    card_name = str(
        candidate_row[
            "card_name"
        ]
    )

    move_name = str(
        candidate_row[
            "move_name"
        ]
    )

    move_damage = float(
        candidate_row[
            "damage"
        ]
    )

    initial_state = build_candidate_transition_state(
        card_name=card_name,
        move_name=move_name,
        damage=move_damage,
    )

    candidate_move = (
        initial_state
        .player
        .active
        .card[
            "moves"
        ][0]
    )

    initial_player_hp = float(
        initial_state
        .player
        .active
        .current_hp
    )

    initial_opponent_hp = float(
        initial_state
        .opponent
        .active
        .current_hp
    )

    initial_turn_number = int(
        initial_state
        .turn_number
    )

    initial_current_player = str(
        initial_state
        .current_player
    )

    transition_error_type = ""
    transition_error_message = ""

    try:

        next_state = apply_move54(
            initial_state,
            candidate_move,
        )

        returned_battle_state = isinstance(
            next_state,
            BattleState54,
        )

        returned_new_state = (
            next_state
            is not initial_state
        )

        expected_opponent_hp = max(
            initial_opponent_hp
            - move_damage,
            0.0,
        )

        actual_opponent_hp = float(
            next_state
            .opponent
            .active
            .current_hp
        )

        actual_player_hp = float(
            next_state
            .player
            .active
            .current_hp
        )

        damage_applied = (
            initial_opponent_hp
            - actual_opponent_hp
        )

        original_state_unchanged = (
            float(
                initial_state
                .opponent
                .active
                .current_hp
            )
            == initial_opponent_hp
            and float(
                initial_state
                .player
                .active
                .current_hp
            )
            == initial_player_hp
            and int(
                initial_state.turn_number
            )
            == initial_turn_number
            and str(
                initial_state.current_player
            )
            == initial_current_player
        )

        expected_damage_applied = np.isclose(
            damage_applied,
            move_damage,
        )

        expected_hp_reached = np.isclose(
            actual_opponent_hp,
            expected_opponent_hp,
        )

        player_hp_unchanged = np.isclose(
            actual_player_hp,
            initial_player_hp,
        )

        turn_advanced = (
            int(
                next_state.turn_number
            )
            ==
            initial_turn_number + 1
        )

        side_switched = (
            str(
                next_state.current_player
            )
            == "Opponent"
        )

        hp_nonnegative = (
            actual_player_hp >= 0.0
            and actual_opponent_hp >= 0.0
        )

        transition_passed = all(
            [
                returned_battle_state,
                returned_new_state,
                original_state_unchanged,
                expected_damage_applied,
                expected_hp_reached,
                player_hp_unchanged,
                turn_advanced,
                side_switched,
                hp_nonnegative,
            ]
        )

    except Exception as error:

        next_state = None

        returned_battle_state = False
        returned_new_state = False
        original_state_unchanged = True
        expected_damage_applied = False
        expected_hp_reached = False
        player_hp_unchanged = False
        turn_advanced = False
        side_switched = False
        hp_nonnegative = False
        damage_applied = np.nan
        actual_player_hp = np.nan
        actual_opponent_hp = np.nan
        transition_passed = False

        transition_error_type = type(
            error
        ).__name__

        transition_error_message = str(
            error
        )

    candidate_transition_rows.append(
        {
            "candidate_number":
                candidate_index + 1,

            "card_name":
                card_name,

            "move_name":
                move_name,

            "declared_damage":
                move_damage,

            "initial_player_hp":
                initial_player_hp,

            "initial_opponent_hp":
                initial_opponent_hp,

            "actual_player_hp":
                actual_player_hp,

            "actual_opponent_hp":
                actual_opponent_hp,

            "damage_applied":
                damage_applied,

            "returned_battle_state":
                returned_battle_state,

            "returned_new_state":
                returned_new_state,

            "original_state_unchanged":
                original_state_unchanged,

            "expected_damage_applied":
                expected_damage_applied,

            "expected_hp_reached":
                expected_hp_reached,

            "player_hp_unchanged":
                player_hp_unchanged,

            "turn_advanced":
                turn_advanced,

            "side_switched":
                side_switched,

            "hp_nonnegative":
                hp_nonnegative,

            "transition_passed":
                transition_passed,

            "error_type":
                transition_error_type,

            "error_message":
                transition_error_message,

            "source_files":
                candidate_row[
                    "source_files"
                ],
        }
    )


section4b_candidate_transitions_df = pd.DataFrame(
    candidate_transition_rows
)


