def prepare_section4b_export(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """
    Encode nested values for stable CSV output.

    Handles:
    - empty DataFrames,
    - categorical columns,
    - lists, tuples, sets, and dictionaries.
    """

    export_df = dataframe.copy()

    if export_df.empty:

        return export_df.astype(
            object
        )

    for column_name in export_df.columns:

        column_series = export_df[
            column_name
        ]

        # Convert categorical columns before applying object checks.
        if isinstance(
            column_series.dtype,
            pd.CategoricalDtype,
        ):

            export_df[
                column_name
            ] = column_series.astype(
                object
            )

            column_series = export_df[
                column_name
            ]

        nested_mask = column_series.map(
            lambda value: isinstance(
                value,
                (
                    list,
                    tuple,
                    set,
                    dict,
                ),
            )
        )

        has_nested_values = bool(
            nested_mask.to_numpy(
                dtype=bool
            ).any()
        )

        if has_nested_values:

            export_df[
                column_name
            ] = column_series.map(
                lambda value: json.dumps(
                    (
                        list(
                            value
                        )
                        if isinstance(
                            value,
                            set,
                        )
                        else value
                    ),
                    ensure_ascii=False,
                )
                if isinstance(
                    value,
                    (
                        list,
                        tuple,
                        set,
                        dict,
                    ),
                )
                else value
            )

    return export_df

