# 2. Supported reference-file types
# --------------------------------------------------------------------------------------

REFERENCE_SUFFIXES = {
    ".pdf",
    ".png",
    ".jpg",
    ".jpeg",
    ".webp",
    ".txt",
    ".md",
    ".ipynb",
    ".html",
    ".htm",
    ".zip",
    ".7z",
    ".tar",
    ".gz",
    ".yaml",
    ".yml",
    ".xml",
}


EXCLUDED_REFERENCE_DIRECTORIES = {
    ".git",
    ".ipynb_checkpoints",
    "__pycache__",
    ".venv",
    "venv",
    "env",
    "node_modules",
}


REFERENCE_KEYWORDS = [
    "card",
    "cards",
    "pokemon",
    "reference",
    "metadata",
    "image",
    "images",
    "rule",
    "rulebook",
    "expansion",
    "set",
    "identifier",
    "mapping",
    "catalog",
    "challenge",
    "ptcg",
    "battle",
]


TOURNAMENT_CARD_NAMES = [
    "Bulbasaur",
    "Charmander",
    "Eevee",
    "Meowth",
]


# --------------------------------------------------------------------------------------
# 3. File-path helpers
# --------------------------------------------------------------------------------------

def reference_path_is_excluded(
    file_path: Path,
) -> bool:
    """
    Return True when a path belongs to an excluded environment directory.
    """

    return any(
        path_part in EXCLUDED_REFERENCE_DIRECTORIES
        for path_part in file_path.parts
    )


def reference_file_score(
    file_path: Path,
) -> int:
    """
    Score likely relevance using path and filename evidence.
    """

    path_text = str(
        file_path
    ).lower()

    file_name = file_path.name.lower()

    score = 0

    for keyword in REFERENCE_KEYWORDS:

        if keyword in file_name:

            score += 3

        elif keyword in path_text:

            score += 1

    for card_name in TOURNAMENT_CARD_NAMES:

        if card_name.lower() in file_name:

            score += 8

        elif card_name.lower() in path_text:

            score += 4

    if file_path.suffix.lower() in {
        ".pdf",
        ".png",
        ".jpg",
        ".jpeg",
        ".webp",
    }:

        score += 2

    if any(
        directory_name in path_text
        for directory_name in [
            "\\input\\",
            "\\inputs\\",
            "\\reference\\",
            "\\references\\",
            "\\raw\\",
            "\\cards\\",
            "\\images\\",
            "\\kaggle\\",
        ]
    ):

        score += 5

    return score


# --------------------------------------------------------------------------------------
# 4. Project-wide reference inventory
# --------------------------------------------------------------------------------------

reference_inventory_rows = []


for file_path in PROJECT_ROOT.rglob(
    "*"
):

    if not file_path.is_file():

        continue

    if reference_path_is_excluded(
        file_path
    ):

        continue

    suffix = file_path.suffix.lower()

    if suffix not in REFERENCE_SUFFIXES:

        continue

    file_name_lower = file_path.name.lower()

    card_name_hits = [
        card_name
        for card_name in TOURNAMENT_CARD_NAMES
        if card_name.lower() in file_name_lower
        or card_name.lower() in str(
            file_path
        ).lower()
    ]

    keyword_hits = [
        keyword
        for keyword in REFERENCE_KEYWORDS
        if keyword in file_name_lower
        or keyword in str(
            file_path
        ).lower()
    ]

    reference_inventory_rows.append(
        {
            "path":
                str(
                    file_path
                ),

            "file_name":
                file_path.name,

            "suffix":
                suffix,

            "size_bytes":
                int(
                    file_path.stat().st_size
                ),

            "card_name_hits":
                card_name_hits,

            "keyword_hits":
                keyword_hits,

            "relevance_score":
                int(
                    reference_file_score(
                        file_path
                    )
                ),
        }
    )


section4e_reference_inventory_df = pd.DataFrame(
    reference_inventory_rows
)


