# --------------------------------------------------------------------------------------
# 7. Safely search readable text files
# --------------------------------------------------------------------------------------

TEXT_SEARCH_SUFFIXES = {
    ".txt",
    ".md",
    ".html",
    ".htm",
    ".yaml",
    ".yml",
    ".xml",
    ".ipynb",
}


text_match_rows = []


for inventory_row in (
    section4e_reference_inventory_df.to_dict(
        orient="records"
    )
    if not section4e_reference_inventory_df.empty
    else []
):

    file_path = Path(
        inventory_row[
            "path"
        ]
    )

    if file_path.suffix.lower() not in TEXT_SEARCH_SUFFIXES:

        continue

    try:

        source_text = file_path.read_text(
            encoding="utf-8",
            errors="ignore",
        )

    except Exception:

        continue

    source_text_lower = source_text.lower()

    for card_name in TOURNAMENT_CARD_NAMES:

        card_name_lower = card_name.lower()

        occurrence_count = source_text_lower.count(
            card_name_lower
        )

        if occurrence_count == 0:

            continue

        context_fragments = []

        search_start = 0

        for _ in range(
            min(
                occurrence_count,
                5,
            )
        ):

            match_index = source_text_lower.find(
                card_name_lower,
                search_start,
            )

            if match_index < 0:

                break

            context_start = max(
                match_index - 120,
                0,
            )

            context_end = min(
                match_index + 240,
                len(
                    source_text
                ),
            )

            context_fragment = (
                source_text[
                    context_start:context_end
                ]
                .replace(
                    "\n",
                    " ",
                )
                .replace(
                    "\r",
                    " ",
                )
            )

            context_fragments.append(
                context_fragment
            )

            search_start = (
                match_index
                + len(
                    card_name_lower
                )
            )

        text_match_rows.append(
            {
                "source_file":
                    str(
                        file_path
                    ),

                "file_name":
                    file_path.name,

                "card_name":
                    card_name,

                "occurrence_count":
                    int(
                        occurrence_count
                    ),

                "context_fragments":
                    context_fragments,

                "relevance_score":
                    int(
                        inventory_row[
                            "relevance_score"
                        ]
                    ),
            }
        )


section4e_text_card_matches_df = pd.DataFrame(
    text_match_rows
)


