# --------------------------------------------------------------------------------------
# 3. Notebook JSON extraction helpers
# --------------------------------------------------------------------------------------

def load_notebook_json(
    notebook_path: Path,
) -> Dict[str, Any]:
    """
    Load one notebook as JSON.
    """

    with open(
        notebook_path,
        "r",
        encoding="utf-8",
    ) as file:

        return json.load(
            file
        )


def notebook_cell_text(
    cell: Mapping[str, Any],
) -> str:
    """
    Return combined source and output text for a notebook cell.
    """

    text_parts = []

    source_value = cell.get(
        "source",
        [],
    )

    if isinstance(
        source_value,
        list,
    ):

        text_parts.extend(
            str(
                value
            )
            for value in source_value
        )

    else:

        text_parts.append(
            str(
                source_value
            )
        )

    for output in cell.get(
        "outputs",
        [],
    ):

        if "text" in output:

            output_text = output[
                "text"
            ]

            if isinstance(
                output_text,
                list,
            ):

                text_parts.extend(
                    str(
                        value
                    )
                    for value in output_text
                )

            else:

                text_parts.append(
                    str(
                        output_text
                    )
                )

        output_data = output.get(
            "data",
            {},
        )

        for data_key in [
            "text/plain",
            "text/html",
        ]:

            if data_key not in output_data:

                continue

            data_value = output_data[
                data_key
            ]

            if isinstance(
                data_value,
                list,
            ):

                text_parts.extend(
                    str(
                        value
                    )
                    for value in data_value
                )

            else:

                text_parts.append(
                    str(
                        data_value
                    )
                )

    return "\n".join(
        text_parts
    )


