# --------------------------------------------------------------------------------------
# 6. Extract likely card dictionaries
# --------------------------------------------------------------------------------------

CARD_DICTIONARY_PATTERN = re.compile(
    r"""
    \{
    [^{}]{0,2000}?
    ['"]card_id['"]
    \s*:\s*
    (?P<card_id>\d+)
    [^{}]{0,2000}?
    ['"]name['"]
    \s*:\s*
    ['"](?P<name>[^'"]+)['"]
    [^{}]{0,4000}?
    \}
    """,
    flags=(
        re.IGNORECASE
        |
        re.DOTALL
        |
        re.VERBOSE
    ),
)


card_dictionary_rows = []


for trace_row in section4f_reference_trace_df.to_dict(
    orient="records"
):

    text_excerpt = trace_row[
        "text_excerpt"
    ]

    for dictionary_match in (
        CARD_DICTIONARY_PATTERN.finditer(
            text_excerpt
        )
    ):

        card_name = normalize_card_name(
            dictionary_match.group(
                "name"
            )
        )

        if card_name not in TOURNAMENT_CARDS:

            continue

        dictionary_text = (
            dictionary_match.group(
                0
            )
        )

        expansion_match = re.search(
            r"""['"](?:expansion|set_name|set)['"]\s*:\s*['"]([^'"]+)['"]""",
            dictionary_text,
            flags=re.IGNORECASE,
        )

        hp_match = re.search(
            r"""['"]hp['"]\s*:\s*(\d+(?:\.\d+)?)""",
            dictionary_text,
            flags=re.IGNORECASE,
        )

        image_match = re.search(
            r"""['"](?:image|image_path|image_url)['"]\s*:\s*['"]([^'"]+)['"]""",
            dictionary_text,
            flags=re.IGNORECASE,
        )

        card_dictionary_rows.append(
            {
                "notebook_key":
                    trace_row[
                        "notebook_key"
                    ],

                "cell_index":
                    trace_row[
                        "cell_index"
                    ],

                "card_id":
                    int(
                        dictionary_match.group(
                            "card_id"
                        )
                    ),

                "card_name":
                    card_name,

                "expansion":
                    (
                        expansion_match.group(
                            1
                        )
                        if expansion_match
                        else ""
                    ),

                "hp":
                    (
                        float(
                            hp_match.group(
                                1
                            )
                        )
                        if hp_match
                        else np.nan
                    ),

                "image_reference":
                    (
                        image_match.group(
                            1
                        )
                        if image_match
                        else ""
                    ),

                "dictionary_excerpt":
                    dictionary_text[
                        :3000
                    ],
            }
        )


section4f_card_dictionary_candidates_df = pd.DataFrame(
    card_dictionary_rows
)


if not section4f_card_dictionary_candidates_df.empty:

    section4f_card_dictionary_candidates_df = (
        section4f_card_dictionary_candidates_df
        .drop_duplicates(
            subset=[
                "card_id",
                "card_name",
                "expansion",
            ]
        )
        .sort_values(
            [
                "card_name",
                "card_id",
            ]
        )
        .reset_index(
            drop=True
        )
    )


print()
