import ast
from collections.abc import Mapping


# --------------------------------------------------------------------------------------
# 3. Full notebook output extraction
# --------------------------------------------------------------------------------------

def collect_notebook_output_text(
    cell: Mapping[str, Any],
) -> List[str]:
    """
    Collect source text and all readable output representations
    without truncating the cell.
    """

    collected_text = []

    source_value = cell.get(
        "source",
        [],
    )

    if isinstance(
        source_value,
        list,
    ):

        collected_text.append(
            "".join(
                str(
                    item
                )
                for item in source_value
            )
        )

    else:

        collected_text.append(
            str(
                source_value
            )
        )

    for output in cell.get(
        "outputs",
        [],
    ):

        output_text = output.get(
            "text",
            None,
        )

        if output_text is not None:

            if isinstance(
                output_text,
                list,
            ):

                collected_text.append(
                    "".join(
                        str(
                            item
                        )
                        for item in output_text
                    )
                )

            else:

                collected_text.append(
                    str(
                        output_text
                    )
                )

        output_data = output.get(
            "data",
            {},
        )

        for output_format in [
            "text/plain",
            "application/json",
            "text/html",
        ]:

            if output_format not in output_data:

                continue

            data_value = output_data[
                output_format
            ]

            if isinstance(
                data_value,
                list,
            ):

                collected_text.append(
                    "".join(
                        str(
                            item
                        )
                        for item in data_value
                    )
                )

            else:

                collected_text.append(
                    str(
                        data_value
                    )
                )

    return [
        text_value
        for text_value in collected_text
        if str(
            text_value
        ).strip()
    ]


# --------------------------------------------------------------------------------------
# 4. Recursive object traversal
# --------------------------------------------------------------------------------------

def traverse_nested_objects(
    value: Any,
    object_path: str = "root",
) -> List[Tuple[str, Any]]:
    """
    Return all dictionaries, lists, and scalar values with their paths.
    """

    discovered_objects = [
        (
            object_path,
            value,
        )
    ]

    if isinstance(
        value,
        dict,
    ):

        for key, child_value in value.items():

            discovered_objects.extend(
                traverse_nested_objects(
                    child_value,
                    (
                        f"{object_path}."
                        f"{key}"
                    ),
                )
            )

    elif isinstance(
        value,
        (
            list,
            tuple,
        ),
    ):

        for item_index, child_value in enumerate(
            value
        ):

            discovered_objects.extend(
                traverse_nested_objects(
                    child_value,
                    (
                        f"{object_path}"
                        f"[{item_index}]"
                    ),
                )
            )

    return discovered_objects


def normalize_dictionary_keys(
    dictionary_value: Dict[Any, Any],
) -> Dict[str, Any]:
    """
    Create a lowercase string-key lookup.
    """

    return {
        str(
            key
        ).strip().lower():
            value
        for key, value in dictionary_value.items()
    }


def extract_card_record_from_dictionary(
    dictionary_value: Dict[Any, Any],
) -> Optional[Dict[str, Any]]:
    """
    Extract a tournament-card record from a parsed dictionary.
    """

    normalized_dictionary = normalize_dictionary_keys(
        dictionary_value
    )

    card_id_value = None

    for candidate_key in [
        "card_id",
        "card id",
        "id",
    ]:

        if candidate_key in normalized_dictionary:

            card_id_value = normalized_dictionary[
                candidate_key
            ]

            break

    card_name_value = None

    for candidate_key in [
        "name",
        "card_name",
        "card name",
        "pokemon_name",
    ]:

        if candidate_key in normalized_dictionary:

            card_name_value = normalized_dictionary[
                candidate_key
            ]

            break

    if card_id_value is None or card_name_value is None:

        return None

    card_name = normalize_card_name(
        card_name_value
    )

    if card_name not in TOURNAMENT_CARDS:

        return None

    try:

        card_id = int(
            float(
                card_id_value
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        return None

    expansion_value = ""

    for candidate_key in [
        "expansion",
        "set_name",
        "set name",
        "set",
    ]:

        if candidate_key in normalized_dictionary:

            expansion_value = str(
                normalized_dictionary[
                    candidate_key
                ]
            ).strip()

            break

    hp_value = np.nan

    if "hp" in normalized_dictionary:

        try:

            hp_value = float(
                normalized_dictionary[
                    "hp"
                ]
            )

        except (
            TypeError,
            ValueError,
        ):

            hp_value = np.nan

    attack_value = None

    for candidate_key in [
        "attacks",
        "moves",
        "attack",
        "move",
    ]:

        if candidate_key in normalized_dictionary:

            attack_value = normalized_dictionary[
                candidate_key
            ]

            break

    return {
        "card_id":
            card_id,

        "card_name":
            card_name,

        "expansion":
            expansion_value,

        "hp":
            hp_value,

        "attacks":
            attack_value,

        "full_dictionary":
            dictionary_value,
    }


# --------------------------------------------------------------------------------------
# 5. Extract balanced dictionary fragments
# --------------------------------------------------------------------------------------

def extract_balanced_dictionary_fragments(
    text_value: str,
    maximum_fragments: int = 500,
) -> List[str]:
    """
    Recover balanced {...} fragments while respecting quoted strings.
    """

    fragments = []

    start_index = None
    depth = 0
    quote_character = None
    escape_active = False

    for character_index, character in enumerate(
        text_value
    ):

        if escape_active:

            escape_active = False

            continue

        if character == "\\":

            escape_active = True

            continue

        if quote_character is not None:

            if character == quote_character:

                quote_character = None

            continue

        if character in {
            "'",
            '"',
        }:

            quote_character = character

            continue

        if character == "{":

            if depth == 0:

                start_index = character_index

            depth += 1

        elif character == "}" and depth > 0:

            depth -= 1

            if depth == 0 and start_index is not None:

                fragments.append(
                    text_value[
                        start_index:
                        character_index + 1
                    ]
                )

                start_index = None

                if len(
                    fragments
                ) >= maximum_fragments:

                    break

    return fragments


def safely_parse_python_literal(
    text_value: str,
) -> Optional[Any]:
    """
    Parse a Python literal without executing code.
    """

    try:

        return ast.literal_eval(
            text_value
        )

    except (
        SyntaxError,
        ValueError,
        TypeError,
        MemoryError,
        RecursionError,
    ):

        return None


# --------------------------------------------------------------------------------------
# 6. Search full upstream notebook cells
# --------------------------------------------------------------------------------------

object_recovery_rows = []
proximity_candidate_rows = []


for notebook_key, notebook_path in (
    REFERENCE_NOTEBOOK_PATHS.items()
):

    notebook_json = load_notebook_json(
        notebook_path
    )

    for cell_index, cell in enumerate(
        notebook_json.get(
            "cells",
            [],
        )
    ):

        full_text_values = collect_notebook_output_text(
            cell
        )

        for text_source_index, full_text in enumerate(
            full_text_values
        ):

            full_text_lower = full_text.lower()

            matched_cards = [
                card_name
                for card_name in TOURNAMENT_CARDS
                if card_name.lower()
                in full_text_lower
            ]

            if not matched_cards:

                continue

            # --------------------------------------------------------------------------
            # Method A: parse the complete output when possible
            # --------------------------------------------------------------------------

            full_literal = safely_parse_python_literal(
                full_text.strip()
            )

            parsed_objects = []

            if full_literal is not None:

                parsed_objects.extend(
                    traverse_nested_objects(
                        full_literal
                    )
                )

            # --------------------------------------------------------------------------
            # Method B: parse balanced dictionary fragments
            # --------------------------------------------------------------------------

            dictionary_fragments = (
                extract_balanced_dictionary_fragments(
                    full_text
                )
            )

            for fragment_index, dictionary_fragment in enumerate(
                dictionary_fragments
            ):

                parsed_fragment = safely_parse_python_literal(
                    dictionary_fragment
                )

                if parsed_fragment is None:

                    continue

                parsed_objects.extend(
                    traverse_nested_objects(
                        parsed_fragment,
                        object_path=(
                            f"fragment[{fragment_index}]"
                        ),
                    )
                )

            # --------------------------------------------------------------------------
            # Recover card dictionaries
            # --------------------------------------------------------------------------

            for object_path, parsed_object in parsed_objects:

                if not isinstance(
                    parsed_object,
                    dict,
                ):

                    continue

                recovered_record = (
                    extract_card_record_from_dictionary(
                        parsed_object
                    )
                )

                if recovered_record is None:

                    continue

                object_recovery_rows.append(
                    {
                        "notebook_key":
                            notebook_key,

                        "notebook_path":
                            str(
                                notebook_path
                            ),

                        "cell_index":
                            int(
                                cell_index
                            ),

                        "text_source_index":
                            int(
                                text_source_index
                            ),

                        "object_path":
                            object_path,

                        "card_id":
                            int(
                                recovered_record[
                                    "card_id"
                                ]
                            ),

                        "card_name":
                            recovered_record[
                                "card_name"
                            ],

                        "expansion":
                            recovered_record[
                                "expansion"
                            ],

                        "hp":
                            recovered_record[
                                "hp"
                            ],

                        "attacks":
                            recovered_record[
                                "attacks"
                            ],

                        "full_dictionary":
                            recovered_record[
                                "full_dictionary"
                            ],

                        "recovery_method":
                            "PARSED_DICTIONARY",
                    }
                )

            # --------------------------------------------------------------------------
            # Method C: card-ID/name proximity matching
            # --------------------------------------------------------------------------

            for card_name in matched_cards:

                card_pattern = re.escape(
                    card_name
                )

                proximity_patterns = [
                    re.compile(
                        rf"""
                        card[_\s]*id
                        ['"]?
                        \s*[:=]\s*
                        (?P<card_id>\d+)
                        .{{0,1200}}?
                        ['"]?name['"]?
                        \s*[:=]\s*
                        ['"]{card_pattern}['"]
                        """,
                        flags=(
                            re.IGNORECASE
                            |
                            re.DOTALL
                            |
                            re.VERBOSE
                        ),
                    ),

                    re.compile(
                        rf"""
                        ['"]?name['"]?
                        \s*[:=]\s*
                        ['"]{card_pattern}['"]
                        .{{0,1200}}?
                        card[_\s]*id
                        ['"]?
                        \s*[:=]\s*
                        (?P<card_id>\d+)
                        """,
                        flags=(
                            re.IGNORECASE
                            |
                            re.DOTALL
                            |
                            re.VERBOSE
                        ),
                    ),

                    re.compile(
                        rf"""
                        ['"]card_id['"]
                        \s*:\s*
                        (?P<card_id>\d+)
                        .{{0,1200}}?
                        ['"]name['"]
                        \s*:\s*
                        ['"]{card_pattern}['"]
                        """,
                        flags=(
                            re.IGNORECASE
                            |
                            re.DOTALL
                            |
                            re.VERBOSE
                        ),
                    ),
                ]

                for pattern_index, proximity_pattern in enumerate(
                    proximity_patterns
                ):

                    for proximity_match in proximity_pattern.finditer(
                        full_text
                    ):

                        match_start = max(
                            proximity_match.start() - 300,
                            0,
                        )

                        match_end = min(
                            proximity_match.end() + 1000,
                            len(
                                full_text
                            ),
                        )

                        proximity_candidate_rows.append(
                            {
                                "notebook_key":
                                    notebook_key,

                                "notebook_path":
                                    str(
                                        notebook_path
                                    ),

                                "cell_index":
                                    int(
                                        cell_index
                                    ),

                                "text_source_index":
                                    int(
                                        text_source_index
                                    ),

                                "card_id":
                                    int(
                                        proximity_match.group(
                                            "card_id"
                                        )
                                    ),

                                "card_name":
                                    card_name,

                                "pattern_index":
                                    int(
                                        pattern_index
                                    ),

                                "context_excerpt":
                                    re.sub(
                                        r"\s+",
                                        " ",
                                        full_text[
                                            match_start:
                                            match_end
                                        ],
                                    ).strip(),

                                "recovery_method":
                                    "PROXIMITY_MATCH",
                            }
                        )


section4g_object_recovery_df = pd.DataFrame(
    object_recovery_rows
)

section4g_proximity_candidates_df = pd.DataFrame(
    proximity_candidate_rows
)


