# --------------------------------------------------------------------------------------
# 3. Filename and extension helpers
# --------------------------------------------------------------------------------------

def safe_filename_component(
    value: Any,
) -> str:
    """
    Convert a value into a safe filename component.
    """

    normalized_value = re.sub(
        r"[^A-Za-z0-9._-]+",
        "_",
        str(
            value
        ).strip(),
    )

    normalized_value = normalized_value.strip(
        "._-"
    )

    return (
        normalized_value
        if normalized_value
        else "unknown"
    )


def normalize_image_extension(
    image_name: Any,
    image_data: bytes,
) -> str:
    """
    Resolve a stable image extension from the embedded image name or bytes.
    """

    suffix = Path(
        str(
            image_name
        )
    ).suffix.lower()

    recognized_extensions = {
        ".png",
        ".jpg",
        ".jpeg",
        ".jp2",
        ".jpx",
        ".tif",
        ".tiff",
        ".bmp",
        ".webp",
    }

    if suffix in recognized_extensions:

        return suffix

    # Lightweight signature checks.
    if image_data.startswith(
        b"\x89PNG\r\n\x1a\n"
    ):

        return ".png"

    if image_data.startswith(
        b"\xff\xd8\xff"
    ):

        return ".jpg"

    if image_data.startswith(
        (
            b"II*\x00",
            b"MM\x00*",
        )
    ):

        return ".tiff"

    if image_data.startswith(
        b"BM"
    ):

        return ".bmp"

    if (
        len(
            image_data
        ) >= 12
        and image_data[
            0:4
        ] == b"RIFF"
        and image_data[
            8:12
        ] == b"WEBP"
    ):

        return ".webp"

    return ".bin"


# --------------------------------------------------------------------------------------
# 4. Generic embedded-image extraction
# --------------------------------------------------------------------------------------

def get_page_embedded_images(
    pdf_page: Any,
) -> List[Dict[str, Any]]:
    """
    Return embedded image candidates from one pypdf page.

    Uses page.images when available and records each image's:
    - name,
    - bytes,
    - dimensions,
    - extension,
    - extraction error.
    """

    image_candidates = []

    try:

        page_images = list(
            pdf_page.images
        )

    except Exception as error:

        return [
            {
                "image_index":
                    0,

                "image_name":
                    "",

                "image_data":
                    b"",

                "width":
                    np.nan,

                "height":
                    np.nan,

                "pixel_area":
                    0,

                "size_bytes":
                    0,

                "extension":
                    "",

                "extraction_error_type":
                    type(
                        error
                    ).__name__,

                "extraction_error_message":
                    str(
                        error
                    ),
            }
        ]

    for image_index, image_object in enumerate(
        page_images
    ):

        extraction_error_type = ""
        extraction_error_message = ""

        image_name = str(
            getattr(
                image_object,
                "name",
                f"image_{image_index}",
            )
        )

        try:

            image_data = bytes(
                image_object.data
            )

        except Exception as error:

            image_data = b""

            extraction_error_type = type(
                error
            ).__name__

            extraction_error_message = str(
                error
            )

        image_object_image = getattr(
            image_object,
            "image",
            None,
        )

        width = np.nan
        height = np.nan

        if image_object_image is not None:

            try:

                width = int(
                    image_object_image.width
                )

                height = int(
                    image_object_image.height
                )

            except Exception:

                try:

                    width, height = (
                        image_object_image.size
                    )

                    width = int(
                        width
                    )

                    height = int(
                        height
                    )

                except Exception:

                    width = np.nan
                    height = np.nan

        pixel_area = (
            int(
                width
            )
            *
            int(
                height
            )
            if (
                pd.notna(
                    width
                )
                and pd.notna(
                    height
                )
            )
            else 0
        )

        extension = normalize_image_extension(
            image_name=image_name,
            image_data=image_data,
        )

        image_candidates.append(
            {
                "image_index":
                    int(
                        image_index
                    ),

                "image_name":
                    image_name,

                "image_data":
                    image_data,

                "width":
                    width,

                "height":
                    height,

                "pixel_area":
                    int(
                        pixel_area
                    ),

                "size_bytes":
                    int(
                        len(
                            image_data
                        )
                    ),

                "extension":
                    extension,

                "extraction_error_type":
                    extraction_error_type,

                "extraction_error_message":
                    extraction_error_message,
            }
        )

    return image_candidates


