# --------------------------------------------------------------------------------------
# 4. Parse simulator classes and function signatures
# --------------------------------------------------------------------------------------

import ast


section4t_symbol_rows = []
section4t_attribute_rows = []


for source_name, source_path in SECTION4T_SOURCE_FILES.items():

    source_text = source_path.read_text(
        encoding="utf-8",
        errors="replace",
    )

    parsed_tree = ast.parse(
        source_text
    )

    for node in parsed_tree.body:

        if isinstance(
            node,
            ast.ClassDef,
        ):

            section4t_symbol_rows.append(
                {
                    "source_name":
                        source_name,

                    "symbol_name":
                        node.name,

                    "symbol_type":
                        "class",

                    "line_number":
                        int(
                            node.lineno
                        ),
                }
            )

            for child_node in ast.walk(
                node
            ):

                if isinstance(
                    child_node,
                    ast.AnnAssign,
                ):

                    target_name = (
                        child_node.target.id
                        if isinstance(
                            child_node.target,
                            ast.Name,
                        )
                        else ""
                    )

                    annotation_text = (
                        ast.unparse(
                            child_node.annotation
                        )
                        if hasattr(
                            ast,
                            "unparse",
                        )
                        else ""
                    )

                    section4t_attribute_rows.append(
                        {
                            "source_name":
                                source_name,

                            "class_name":
                                node.name,

                            "attribute_name":
                                target_name,

                            "annotation":
                                annotation_text,

                            "line_number":
                                int(
                                    child_node.lineno
                                ),

                            "energy_related":
                                (
                                    "energy"
                                    in target_name.lower()
                                    or "energy"
                                    in annotation_text.lower()
                                ),
                        }
                    )

                elif isinstance(
                    child_node,
                    ast.Assign,
                ):

                    for assignment_target in child_node.targets:

                        if isinstance(
                            assignment_target,
                            ast.Attribute,
                        ):

                            attribute_name = (
                                assignment_target.attr
                            )

                            section4t_attribute_rows.append(
                                {
                                    "source_name":
                                        source_name,

                                    "class_name":
                                        node.name,

                                    "attribute_name":
                                        attribute_name,

                                    "annotation":
                                        "",

                                    "line_number":
                                        int(
                                            child_node.lineno
                                        ),

                                    "energy_related":
                                        (
                                            "energy"
                                            in attribute_name.lower()
                                        ),
                                }
                            )

        elif isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
            ),
        ):

            section4t_symbol_rows.append(
                {
                    "source_name":
                        source_name,

                    "symbol_name":
                        node.name,

                    "symbol_type":
                        "function",

                    "line_number":
                        int(
                            node.lineno
                        ),
                }
            )


section4t_source_symbols_df = pd.DataFrame(
    section4t_symbol_rows
)


section4t_state_attributes_df = pd.DataFrame(
    section4t_attribute_rows
)


if not section4t_state_attributes_df.empty:

    section4t_state_attributes_df = (
        section4t_state_attributes_df
        .drop_duplicates(
            subset=[
                "source_name",
                "class_name",
                "attribute_name",
                "line_number",
            ]
        )
        .sort_values(
            [
                "source_name",
                "class_name",
                "line_number",
            ]
        )
        .reset_index(
            drop=True
        )
    )


