# --------------------------------------------------------------------------------------
# 5. Energy extraction helper
# --------------------------------------------------------------------------------------

ENERGY_ATTRIBUTE_CANDIDATES = [
    "attached_energy",
    "energy",
    "energy_count",
    "energies",
]


def normalize_energy_value(
    value: Any,
) -> Optional[float]:
    """
    Convert common simulator energy representations into a numeric count.
    """

    if value is None:

        return None

    if isinstance(
        value,
        bool,
    ):

        return float(
            int(
                value
            )
        )

    if isinstance(
        value,
        (
            int,
            float,
            np.integer,
            np.floating,
        ),
    ):

        if pd.isna(
            value
        ):

            return None

        return float(
            value
        )

    if isinstance(
        value,
        (
            list,
            tuple,
            set,
        ),
    ):

        return float(
            len(
                value
            )
        )

    if isinstance(
        value,
        dict,
    ):

        numeric_dictionary_values = []

        for dictionary_value in value.values():

            try:

                numeric_dictionary_values.append(
                    float(
                        dictionary_value
                    )
                )

            except (
                TypeError,
                ValueError,
            ):

                continue

        if numeric_dictionary_values:

            return float(
                sum(
                    numeric_dictionary_values
                )
            )

        return float(
            len(
                value
            )
        )

    try:

        numeric_value = float(
            value
        )

        if pd.isna(
            numeric_value
        ):

            return None

        return numeric_value

    except (
        TypeError,
        ValueError,
    ):

        return None


def extract_object_energy(
    pokemon_object: Any,
) -> Dict[str, Any]:
    """
    Extract energy from a Pokémon-like simulator object without modifying it.
    """

    extraction_result = {
        "energy_value":
            None,

        "energy_attribute":
            "",

        "energy_observed":
            False,

        "energy_raw_type":
            "",

        "energy_extraction_status":
            "NO_ENERGY_ATTRIBUTE_FOUND",
    }

    if pokemon_object is None:

        extraction_result[
            "energy_extraction_status"
        ] = "POKEMON_OBJECT_MISSING"

        return extraction_result

    for attribute_name in ENERGY_ATTRIBUTE_CANDIDATES:

        if not hasattr(
            pokemon_object,
            attribute_name,
        ):

            continue

        raw_value = getattr(
            pokemon_object,
            attribute_name,
        )

        numeric_value = normalize_energy_value(
            raw_value
        )

        extraction_result[
            "energy_attribute"
        ] = attribute_name

        extraction_result[
            "energy_raw_type"
        ] = type(
            raw_value
        ).__name__

        if numeric_value is not None:

            extraction_result[
                "energy_value"
            ] = numeric_value

            extraction_result[
                "energy_observed"
            ] = True

            extraction_result[
                "energy_extraction_status"
            ] = "ENERGY_EXTRACTED"

        else:

            extraction_result[
                "energy_extraction_status"
            ] = "ENERGY_ATTRIBUTE_NOT_NUMERIC"

        return extraction_result

    return extraction_result


def extract_side_state(
    battle_state: Any,
    side_name: str,
) -> Dict[str, Any]:
    """
    Extract active-card and energy evidence for one battle side.
    """

    normalized_side = str(
        side_name
    ).strip().lower()

    side_attribute_candidates = {
        "player": [
            "player",
            "player_state",
        ],

        "opponent": [
            "opponent",
            "opponent_state",
        ],
    }

    side_object = None
    side_attribute_used = ""

    for attribute_name in side_attribute_candidates.get(
        normalized_side,
        [],
    ):

        if hasattr(
            battle_state,
            attribute_name,
        ):

            side_object = getattr(
                battle_state,
                attribute_name,
            )

            side_attribute_used = attribute_name

            break

    if side_object is None:

        return {
            "side":
                side_name,

            "side_attribute":
                "",

            "active_card":
                "",

            "active_object_found":
                False,

            "energy_value":
                None,

            "energy_attribute":
                "",

            "energy_observed":
                False,

            "energy_extraction_status":
                "SIDE_OBJECT_NOT_FOUND",
        }

    active_object = getattr(
        side_object,
        "active",
        None,
    )

    card_object = getattr(
        active_object,
        "card",
        None,
    )

    active_card_name = ""

    if isinstance(
        card_object,
        dict,
    ):

        active_card_name = str(
            card_object.get(
                "name",
                "",
            )
        )

    elif card_object is not None:

        active_card_name = str(
            getattr(
                card_object,
                "name",
                "",
            )
        )

    if not active_card_name and active_object is not None:

        active_card_name = str(
            getattr(
                active_object,
                "name",
                "",
            )
        )

    energy_result = extract_object_energy(
        active_object
    )

    return {
        "side":
            side_name,

        "side_attribute":
            side_attribute_used,

        "active_card":
            active_card_name,

        "active_object_found":
            active_object is not None,

        **energy_result,
    }


