SECTION4T_INSTRUMENTATION_COLUMNS = [
    "scenario_id",
    "condition_id",
    "decision_number",
    "turn_number",
    "acting_side",
    "active_card",
    "acting_energy",
    "acting_energy_observed",
    "acting_energy_attribute",
    "defending_card",
    "defending_energy",
    "defending_energy_observed",
    "defending_energy_attribute",
    "legal_moves",
    "legal_move_count",
    "selected_move",
    "selected_move_is_control_action",
    "verified_energy_requirement",
    "selected_attack_energy_ready",
    "energy_validation_status",
    "routing_reason",
    "confidence",
]


def build_energy_instrumentation_record(
    *,
    battle_state: Any,
    scenario_id: str,
    condition_id: str,
    decision_number: int,
    legal_moves: Sequence[Any],
    selected_move: Any,
    routing_reason: str = "",
    confidence: Optional[float] = None,
) -> Dict[str, Any]:
    """
    Build one non-invasive energy instrumentation record.
    """

    current_player_value = str(
        getattr(
            battle_state,
            "current_player",
            "Player",
        )
    )

    acting_side = (
        "Opponent"
        if current_player_value.lower() == "opponent"
        else "Player"
    )

    defending_side = (
        "Player"
        if acting_side == "Opponent"
        else "Opponent"
    )

    acting_profile = extract_side_state(
        battle_state,
        acting_side,
    )

    defending_profile = extract_side_state(
        battle_state,
        defending_side,
    )

    selected_move_name = str(
        selected_move.get(
            "name",
            "",
        )
        if isinstance(
            selected_move,
            dict,
        )
        else selected_move
    ).strip()

    selected_move_is_control_action = (
        selected_move_name
        in SIMULATOR_CONTROL_ACTIONS
    )

    verified_requirement = (
        None
        if selected_move_is_control_action
        else lookup_verified_energy_requirement(
            acting_profile[
                "active_card"
            ],
            selected_move_name,
        )
    )

    acting_energy = acting_profile[
        "energy_value"
    ]

    if selected_move_is_control_action:

        selected_attack_energy_ready = None

        energy_validation_status = (
            "CONTROL_ACTION_NO_ATTACK_COST"
        )

    elif verified_requirement is None:

        selected_attack_energy_ready = None

        energy_validation_status = (
            "VERIFIED_REQUIREMENT_NOT_FOUND"
        )

    elif not acting_profile[
        "energy_observed"
    ]:

        selected_attack_energy_ready = None

        energy_validation_status = (
            "ENERGY_NOT_OBSERVED"
        )

    else:

        selected_attack_energy_ready = bool(
            float(
                acting_energy
            )
            >=
            int(
                verified_requirement
            )
        )

        energy_validation_status = (
            "ENERGY_READY"
            if selected_attack_energy_ready
            else "ENERGY_INSUFFICIENT"
        )

    legal_move_names = sorted(
        {
            str(
                move.get(
                    "name",
                    "",
                )
                if isinstance(
                    move,
                    dict,
                )
                else move
            ).strip()
            for move in legal_moves
            if str(
                move.get(
                    "name",
                    "",
                )
                if isinstance(
                    move,
                    dict,
                )
                else move
            ).strip()
        }
    )

    return {
        "scenario_id":
            str(
                scenario_id
            ),

        "condition_id":
            str(
                condition_id
            ),

        "decision_number":
            int(
                decision_number
            ),

        "turn_number":
            int(
                getattr(
                    battle_state,
                    "turn_number",
                    0,
                )
            ),

        "acting_side":
            acting_side,

        "active_card":
            acting_profile[
                "active_card"
            ],

        "acting_energy":
            acting_energy,

        "acting_energy_observed":
            bool(
                acting_profile[
                    "energy_observed"
                ]
            ),

        "acting_energy_attribute":
            acting_profile[
                "energy_attribute"
            ],

        "defending_card":
            defending_profile[
                "active_card"
            ],

        "defending_energy":
            defending_profile[
                "energy_value"
            ],

        "defending_energy_observed":
            bool(
                defending_profile[
                    "energy_observed"
                ]
            ),

        "defending_energy_attribute":
            defending_profile[
                "energy_attribute"
            ],

        "legal_moves":
            legal_move_names,

        "legal_move_count":
            int(
                len(
                    legal_move_names
                )
            ),

        "selected_move":
            selected_move_name,

        "selected_move_is_control_action":
            bool(
                selected_move_is_control_action
            ),

        "verified_energy_requirement":
            verified_requirement,

        "selected_attack_energy_ready":
            selected_attack_energy_ready,

        "energy_validation_status":
            energy_validation_status,

        "routing_reason":
            str(
                routing_reason
            ),

        "confidence":
            (
                float(
                    confidence
                )
                if confidence is not None
                else np.nan
            ),
    }


