import ast
import pandas as pd


discovered_definition_rows = []


for cell_index, notebook_cell in enumerate(
    notebook53_document.cells
):

    if notebook_cell.cell_type != "code":
        continue

    source_text = str(
        notebook_cell.source
    )

    if not source_text.strip():
        continue

    try:
        parsed_cell = ast.parse(
            source_text
        )

    except SyntaxError:
        continue

    for node in ast.walk(
        parsed_cell
    ):

        if isinstance(
            node,
            ast.ClassDef,
        ):

            definition_type = "class"
            definition_name = node.name

        elif isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
            ),
        ):

            definition_type = "function"
            definition_name = node.name

        else:
            continue

        normalized_name = definition_name.lower()

        adapter_related = any(
            token in normalized_name
            for token in [
                "policy",
                "runner",
                "agent",
                "adapter",
                "legality",
                "battle",
                "move",
                "decision",
            ]
        )

        discovered_definition_rows.append(
            {
                "cell_index":
                    int(
                        cell_index
                    ),

                "definition_type":
                    definition_type,

                "definition_name":
                    definition_name,

                "line_number":
                    int(
                        getattr(
                            node,
                            "lineno",
                            0,
                        )
                    ),

                "adapter_related":
                    bool(
                        adapter_related
                    ),

                "source_excerpt":
                    source_text[
                        :1200
                    ],
            }
        )


section4uc_discovered_definitions_df = pd.DataFrame(
    discovered_definition_rows
)


