import hashlib


def file_sha256(
    file_path: Any,
) -> str:
    """
    Calculate a SHA-256 digest for a local file.
    """

    path_object = Path(
        file_path
    )

    digest = hashlib.sha256()

    with open(
        path_object,
        "rb",
    ) as file:

        for chunk in iter(
            lambda: file.read(
                1024 * 1024
            ),
            b"",
        ):

            digest.update(
                chunk
            )

    return digest.hexdigest()


