def public_instance_attribute_profile(
    instance: Any,
) -> List[Dict[str, Any]]:
    """
    Record public non-callable instance attributes without mutating the instance.
    """

    attribute_rows = []

    for attribute_name in dir(
        instance
    ):

        if attribute_name.startswith(
            "_"
        ):

            continue

        try:

            attribute_value = getattr(
                instance,
                attribute_name,
            )

        except Exception:

            continue

        if callable(
            attribute_value
        ):

            continue

        if isinstance(
            attribute_value,
            (
                str,
                int,
                float,
                bool,
                type(None),
            ),
        ):

            display_value = attribute_value

        elif isinstance(
            attribute_value,
            (
                list,
                tuple,
                set,
                dict,
            ),
        ):

            try:

                display_value = str(
                    attribute_value
                )[
                    :1000
                ]

            except Exception:

                display_value = (
                    f"<{type(attribute_value).__name__}>"
                )

        else:

            display_value = (
                f"<{type(attribute_value).__name__}>"
            )

        attribute_rows.append(
            {
                "attribute_name":
                    attribute_name,

                "attribute_type":
                    type(
                        attribute_value
                    ).__name__,

                "attribute_value":
                    display_value,
            }
        )

    return attribute_rows


