# --------------------------------------------------------------------------------------
# 3. General value-extraction helpers
# --------------------------------------------------------------------------------------

def normalize_record_value(
    value: Any,
) -> Any:
    """
    Convert dataclass, mapping, object, or scalar values into exportable values.
    """

    if value is None:

        return None

    if is_dataclass(
        value
    ):

        return asdict(
            value
        )

    if isinstance(
        value,
        Mapping,
    ):

        return dict(
            value
        )

    if isinstance(
        value,
        (
            str,
            int,
            float,
            bool,
            list,
            tuple,
            set,
            dict,
        ),
    ):

        return value

    if hasattr(
        value,
        "__dict__",
    ):

        return {
            key:
                item_value
            for key, item_value in vars(
                value
            ).items()
            if not str(
                key
            ).startswith(
                "_"
            )
        }

    return value


def get_record_field(
    record: Any,
    candidate_names: Sequence[str],
    default: Any = None,
) -> Any:
    """
    Recover a value from a dictionary, dataclass, pandas row, or object.
    """

    if record is None:

        return default

    if isinstance(
        record,
        pd.Series,
    ):

        for field_name in candidate_names:

            if field_name in record.index:

                field_value = record[
                    field_name
                ]

                if not (
                    pd.isna(
                        field_value
                    )
                    if np.isscalar(
                        field_value
                    )
                    else False
                ):

                    return field_value

    if isinstance(
        record,
        Mapping,
    ):

        for field_name in candidate_names:

            if field_name in record:

                return record[
                    field_name
                ]

    if is_dataclass(
        record
    ):

        record_dictionary = asdict(
            record
        )

        for field_name in candidate_names:

            if field_name in record_dictionary:

                return record_dictionary[
                    field_name
                ]

    for field_name in candidate_names:

        if hasattr(
            record,
            field_name,
        ):

            return getattr(
                record,
                field_name,
            )

    return default


def ensure_action_name(
    action_value: Any,
) -> str:
    """
    Recover a readable action name from a simulator move or AgentDecision.
    """

    if action_value is None:

        return ""

    if isinstance(
        action_value,
        AgentDecision,
    ):

        action_value = getattr(
            action_value,
            "move",
            action_value,
        )

    if isinstance(
        action_value,
        Mapping,
    ):

        return str(
            action_value.get(
                "name",
                action_value.get(
                    "move_name",
                    action_value.get(
                        "action",
                        "",
                    ),
                ),
            )
        ).strip()

    for field_name in [
        "name",
        "move_name",
        "action_name",
    ]:

        if hasattr(
            action_value,
            field_name,
        ):

            return str(
                getattr(
                    action_value,
                    field_name,
                )
            ).strip()

    return str(
        action_value
    ).strip()


def normalize_legal_move_collection(
    legal_moves: Any,
) -> List[str]:
    """
    Convert a legal-action collection into sorted unique action names.
    """

    if legal_moves is None:

        return []

    if isinstance(
        legal_moves,
        str,
    ):

        parsed_moves = parse_serialized_list(
            legal_moves
        )

    elif isinstance(
        legal_moves,
        Mapping,
    ):

        parsed_moves = list(
            legal_moves.values()
        )

    elif isinstance(
        legal_moves,
        (
            list,
            tuple,
            set,
        ),
    ):

        parsed_moves = list(
            legal_moves
        )

    else:

        parsed_moves = [
            legal_moves
        ]

    return sorted(
        {
            ensure_action_name(
                move_value
            )
            for move_value in parsed_moves
            if ensure_action_name(
                move_value
            )
        }
    )


# --------------------------------------------------------------------------------------
# 4. Policy-history extraction helpers
# --------------------------------------------------------------------------------------

POLICY_HISTORY_ATTRIBUTE_CANDIDATES_4VB = [
    "history",
    "decision_history",
    "history_rows",
    "records",
]


def get_policy_history_object(
    policy_agent: Any,
) -> Any:
    """
    Return the strongest available policy-history object.
    """

    for attribute_name in POLICY_HISTORY_ATTRIBUTE_CANDIDATES_4VB:

        if not hasattr(
            policy_agent,
            attribute_name,
        ):

            continue

        history_value = getattr(
            policy_agent,
            attribute_name,
        )

        if callable(
            history_value
        ):

            try:

                history_value = history_value()

            except Exception:

                continue

        if isinstance(
            history_value,
            (
                list,
                tuple,
                pd.DataFrame,
            ),
        ):

            return history_value

    return None


def get_policy_history_length(
    policy_agent: Any,
) -> int:
    """
    Return the number of available policy-history records.
    """

    history_object = get_policy_history_object(
        policy_agent
    )

    if history_object is None:

        return 0

    return int(
        len(
            history_object
        )
    )


def get_latest_policy_history_record(
    policy_agent: Any,
    previous_length: int,
) -> Any:
    """
    Return the newest policy-history record created by the last decision.
    """

    history_object = get_policy_history_object(
        policy_agent
    )

    if history_object is None:

        return None

    if len(
        history_object
    ) <= previous_length:

        return None

    if isinstance(
        history_object,
        pd.DataFrame,
    ):

        return history_object.iloc[
            -1
        ]

    return history_object[
        -1
    ]


# --------------------------------------------------------------------------------------
# 5. Instrumented runner wrapper
# --------------------------------------------------------------------------------------

class InstrumentedLegalityAwareRunner:
    """
    Non-invasive wrapper around the reconstructed Notebook 53 battle runner.

    The wrapper records state and energy evidence before returning each decision.
    """

    def __init__(
        self,
        runner: Any,
    ) -> None:

        self.runner = runner
        self.instrumentation_rows = []
        self.current_scenario_id = ""
        self.current_condition_id = ""
        self.decision_number = 0

    def configure_scenario(
        self,
        scenario_id: str,
        condition_id: str,
    ) -> None:

        self.current_scenario_id = str(
            scenario_id
        )

        self.current_condition_id = str(
            condition_id
        )

        self.decision_number = 0

    def reset(
        self,
    ) -> None:

        self.runner.reset()
        self.decision_number = 0

    def choose_move(
        self,
        state: Any,
        depth: Optional[int] = None,
    ) -> Any:

        self.decision_number += 1

        policy_agent = getattr(
            self.runner,
            "policy_agent",
            notebook54_legality_policy,
        )

        previous_history_length = (
            get_policy_history_length(
                policy_agent
            )
        )

        decision = self.runner.choose_move(
            state,
            depth=depth,
        )

        latest_history_record = (
            get_latest_policy_history_record(
                policy_agent,
                previous_history_length,
            )
        )

        selected_move_name = ensure_action_name(
            decision
        )

        if not selected_move_name:

            selected_move_name = ensure_action_name(
                get_record_field(
                    latest_history_record,
                    [
                        "selected_move",
                        "move",
                        "action",
                    ],
                    "",
                )
            )

        legal_moves = normalize_legal_move_collection(
            get_record_field(
                latest_history_record,
                [
                    "legal_moves",
                    "legal_move_names",
                    "available_moves",
                    "legal_actions",
                ],
                None,
            )
        )

        legal_move_source = (
            "POLICY_HISTORY"
            if legal_moves
            else "SELECTED_MOVE_FALLBACK"
        )

        if not legal_moves and selected_move_name:

            legal_moves = [
                selected_move_name
            ]

        routing_reason = str(
            get_record_field(
                latest_history_record,
                [
                    "routing_reason",
                    "route_reason",
                    "decision_reason",
                ],
                "",
            )
        )

        confidence_value = get_record_field(
            latest_history_record,
            [
                "confidence",
                "prediction_confidence",
                "selected_probability",
            ],
            np.nan,
        )

        try:

            confidence_value = float(
                confidence_value
            )

        except (
            TypeError,
            ValueError,
        ):

            confidence_value = np.nan

        instrumentation_record = (
            build_energy_instrumentation_record(
                battle_state=state,
                scenario_id=self.current_scenario_id,
                condition_id=self.current_condition_id,
                decision_number=self.decision_number,
                legal_moves=legal_moves,
                selected_move=selected_move_name,
                routing_reason=routing_reason,
                confidence=confidence_value,
            )
        )

        instrumentation_record[
            "legal_move_source"
        ] = legal_move_source

        instrumentation_record[
            "policy_history_record_available"
        ] = latest_history_record is not None

        instrumentation_record[
            "runner_decision_type"
        ] = type(
            decision
        ).__name__

        instrumentation_record[
            "runner_depth_argument"
        ] = (
            int(
                depth
            )
            if depth is not None
            else int(
                getattr(
                    self.runner,
                    "default_search_depth",
                    0,
                )
            )
        )

        instrumentation_record[
            "instrumentation_sequence"
        ] = int(
            len(
                self.instrumentation_rows
            )
            +
            1
        )

        self.instrumentation_rows.append(
            instrumentation_record
        )

        return decision

    def statistics(
        self,
    ) -> Dict[str, Any]:

        runner_statistics = self.runner.statistics()

        return {
            **runner_statistics,

            "instrumented_decisions":
                int(
                    len(
                        self.instrumentation_rows
                    )
                ),
        }


