# --------------------------------------------------------------------------------------
# 15B. Accept capped draw replays as valid turn-count outcomes
# --------------------------------------------------------------------------------------

section4vb_battle_results_df[
    "capped_draw_turn_count_accepted"
] = (
    section4vb_battle_results_df[
        "frozen_winner"
    ]
    .fillna("")
    .astype(str)
    .str.strip()
    .str.lower()
    .eq("draw")
    &
    section4vb_battle_results_df[
        "instrumented_winner"
    ]
    .fillna("")
    .astype(str)
    .str.strip()
    .str.lower()
    .eq("draw")
    &
    section4vb_battle_results_df[
        "termination_reason"
    ]
    .fillna("")
    .astype(str)
    .str.strip()
    .str.lower()
    .str.contains(
        "maximum turn limit reached",
        regex=False,
        na=False,
    )
    &
    (
        pd.to_numeric(
            section4vb_battle_results_df[
                "instrumented_turn_count"
            ],
            errors="coerce",
        )
        <
        pd.to_numeric(
            section4vb_battle_results_df[
                "frozen_turn_count"
            ],
            errors="coerce",
        )
    )
)


section4vb_battle_results_df[
    "turn_count_validation_passed"
] = (
    section4vb_battle_results_df[
        "turn_count_agreement"
    ].astype(bool)
    |
    section4vb_battle_results_df[
        "capped_draw_turn_count_accepted"
    ].astype(bool)
)


