import ast
from typing import Any, Dict, List, Optional


# --------------------------------------------------------------------------------------
# 1. Generic record-field extraction
# --------------------------------------------------------------------------------------

def get_record_field(
    record: Any,
    candidate_names: List[str],
    default: Any = None,
) -> Any:
    """
    Return the first available field from a dictionary, pandas Series,
    named object, or other mapping-like record.
    """

    if record is None:
        return default

    for field_name in candidate_names:

        # Dictionary or mapping-like access.
        if isinstance(record, dict):

            if field_name in record:
                return record[field_name]

        # Pandas Series access.
        if isinstance(record, pd.Series):

            if field_name in record.index:
                return record[field_name]

        # Normal object attribute.
        if hasattr(record, field_name):

            try:
                return getattr(record, field_name)

            except Exception:
                pass

        # Generic get() method.
        get_method = getattr(
            record,
            "get",
            None,
        )

        if callable(get_method):

            try:

                value = get_method(
                    field_name,
                    None,
                )

                if value is not None:
                    return value

            except Exception:
                pass

    return default


# --------------------------------------------------------------------------------------
# 2. Convert decisions, actions, and move records to a move name
# --------------------------------------------------------------------------------------

def ensure_action_name(
    action_value: Any,
) -> str:
    """
    Convert a simulator decision, move dictionary, object, or raw string
    into a normalized move-name string.
    """

    if action_value is None:
        return ""

    if isinstance(action_value, str):
        return action_value.strip()

    if isinstance(action_value, dict):

        for field_name in [
            "name",
            "move_name",
            "selected_move",
            "move",
            "action",
        ]:

            if field_name in action_value:

                return ensure_action_name(
                    action_value[field_name]
                )

        return ""

    # A BattleDecision-style object may contain .move.
    if hasattr(action_value, "move"):

        try:

            return ensure_action_name(
                getattr(
                    action_value,
                    "move",
                )
            )

        except Exception:
            pass

    # A move object may expose .name.
    if hasattr(action_value, "name"):

        try:

            return str(
                getattr(
                    action_value,
                    "name",
                )
            ).strip()

        except Exception:
            pass

    return str(
        action_value
    ).strip()


# --------------------------------------------------------------------------------------
# 3. Normalize legal-move collections
# --------------------------------------------------------------------------------------

def normalize_legal_move_collection(
    legal_move_value: Any,
) -> List[str]:
    """
    Normalize legal actions supplied as a list, tuple, set, dictionary,
    serialized Python list, comma-separated string, or single move.
    """

    if legal_move_value is None:
        return []

    parsed_value = legal_move_value

    if isinstance(
        legal_move_value,
        str,
    ):

        stripped_value = legal_move_value.strip()

        if not stripped_value:
            return []

        try:

            parsed_value = ast.literal_eval(
                stripped_value
            )

        except Exception:

            if "," in stripped_value:

                parsed_value = [
                    item.strip()
                    for item in stripped_value.split(",")
                    if item.strip()
                ]

            else:

                parsed_value = [
                    stripped_value
                ]

    if isinstance(
        parsed_value,
        dict,
    ):

        if "legal_moves" in parsed_value:

            parsed_value = parsed_value[
                "legal_moves"
            ]

        elif "moves" in parsed_value:

            parsed_value = parsed_value[
                "moves"
            ]

        else:

            parsed_value = list(
                parsed_value.values()
            )

    if not isinstance(
        parsed_value,
        (
            list,
            tuple,
            set,
        ),
    ):

        parsed_value = [
            parsed_value
        ]

    normalized_moves = []

    for move_value in parsed_value:

        move_name = ensure_action_name(
            move_value
        )

        if (
            move_name
            and move_name not in normalized_moves
        ):

            normalized_moves.append(
                move_name
            )

    return normalized_moves


# --------------------------------------------------------------------------------------
# 4. Locate policy-history storage
# --------------------------------------------------------------------------------------

def get_policy_history_container(
    policy_agent: Any,
) -> Any:
    """
    Recover the policy decision-history container from the production agent.
    """

    if policy_agent is None:
        return []

    for attribute_name in [
        "decision_history",
        "policy_history",
        "history",
        "routing_history",
        "prediction_history",
        "selection_history",
    ]:

        if hasattr(
            policy_agent,
            attribute_name,
        ):

            try:

                history_value = getattr(
                    policy_agent,
                    attribute_name,
                )

                if history_value is not None:
                    return history_value

            except Exception:
                pass

    statistics_method = getattr(
        policy_agent,
        "statistics",
        None,
    )

    if callable(
        statistics_method,
    ):

        try:

            statistics_value = statistics_method()

            if isinstance(
                statistics_value,
                dict,
            ):

                for field_name in [
                    "decision_history",
                    "policy_history",
                    "history",
                ]:

                    if field_name in statistics_value:

                        return statistics_value[
                            field_name
                        ]

        except Exception:
            pass

    return []


def get_policy_history_length(
    policy_agent: Any,
) -> int:
    """
    Return the current number of recorded policy decisions.
    """

    history_container = get_policy_history_container(
        policy_agent
    )

    try:

        return int(
            len(
                history_container
            )
        )

    except Exception:

        return 0


def get_latest_policy_history_record(
    policy_agent: Any,
    previous_history_length: int,
) -> Any:
    """
    Return the newest policy-history row created after a decision.
    """

    history_container = get_policy_history_container(
        policy_agent
    )

    try:

        current_history_length = len(
            history_container
        )

    except Exception:

        return None

    if current_history_length <= 0:
        return None

    # Prefer a newly created record.
    if current_history_length > int(
        previous_history_length
    ):

        try:

            if isinstance(
                history_container,
                pd.DataFrame,
            ):

                return history_container.iloc[
                    -1
                ].to_dict()

            if isinstance(
                history_container,
                pd.Series,
            ):

                return history_container.to_dict()

            return history_container[
                -1
            ]

        except Exception:
            pass

    # The agent may update its latest record in place.
    try:

        if isinstance(
            history_container,
            pd.DataFrame,
        ):

            return history_container.iloc[
                -1
            ].to_dict()

        if isinstance(
            history_container,
            pd.Series,
        ):

            return history_container.to_dict()

        return history_container[
            -1
        ]

    except Exception:

        return None


# --------------------------------------------------------------------------------------
# 5. Safe battle-side state extraction
# --------------------------------------------------------------------------------------

def extract_instrumentation_side_state(
    battle_state: Any,
    side_name: str,
) -> Dict[str, Any]:
    """
    Recover active card, HP, and energy from either Player or Opponent.
    """

    side_label = str(
        side_name
    ).strip().title()

    # Prefer the already validated Section 4U extraction helper.
    existing_extractor = globals().get(
        "extract_side_state"
    )

    if callable(
        existing_extractor
    ):

        try:

            profile = existing_extractor(
                battle_state,
                side_label,
            )

            if isinstance(
                profile,
                dict,
            ):

                return profile

        except Exception:
            pass

    side_attribute = (
        "player"
        if side_label == "Player"
        else "opponent"
    )

    player_state = getattr(
        battle_state,
        side_attribute,
        None,
    )

    active_pokemon = getattr(
        player_state,
        "active",
        None,
    )

    card_value = getattr(
        active_pokemon,
        "card",
        {},
    )

    if not isinstance(
        card_value,
        dict,
    ):

        card_value = {}

    active_card_name = str(
        card_value.get(
            "name",
            "",
        )
    )

    current_hp = getattr(
        active_pokemon,
        "current_hp",
        np.nan,
    )

    attached_energy = getattr(
        active_pokemon,
        "attached_energy",
        np.nan,
    )

    energy_observed = not pd.isna(
        attached_energy
    )

    return {
        "active_card":
            active_card_name,

        "hp_value":
            current_hp,

        "hp_observed":
            not pd.isna(
                current_hp
            ),

        "energy_value":
            attached_energy,

        "energy_observed":
            bool(
                energy_observed
            ),
    }


# --------------------------------------------------------------------------------------
# 6. Construct one complete energy-instrumentation record
# --------------------------------------------------------------------------------------

def build_energy_instrumentation_record(
    battle_state: Any,
    scenario_id: str,
    condition_id: str,
    decision_number: int,
    legal_moves: List[str],
    selected_move: str,
    routing_reason: str,
    confidence: float,
) -> Dict[str, Any]:
    """
    Capture state, side, card, HP, energy, legal moves, and decision evidence
    immediately before the simulator applies the selected move.
    """

    current_player = str(
        getattr(
            battle_state,
            "current_player",
            "",
        )
    ).strip().title()

    if current_player not in {
        "Player",
        "Opponent",
    }:

        current_player = "Player"

    opposing_side = (
        "Opponent"
        if current_player == "Player"
        else "Player"
    )

    acting_profile = (
        extract_instrumentation_side_state(
            battle_state,
            current_player,
        )
    )

    opposing_profile = (
        extract_instrumentation_side_state(
            battle_state,
            opposing_side,
        )
    )

    acting_energy_value = (
        acting_profile.get(
            "energy_value",
            np.nan,
        )
    )

    opposing_energy_value = (
        opposing_profile.get(
            "energy_value",
            np.nan,
        )
    )

    acting_energy_observed = bool(
        acting_profile.get(
            "energy_observed",
            not pd.isna(
                acting_energy_value
            ),
        )
    )

    opposing_energy_observed = bool(
        opposing_profile.get(
            "energy_observed",
            not pd.isna(
                opposing_energy_value
            ),
        )
    )

    normalized_legal_moves = (
        normalize_legal_move_collection(
            legal_moves
        )
    )

    selected_move_name = ensure_action_name(
        selected_move
    )

    selected_move_is_legal = (
        selected_move_name
        in normalized_legal_moves
        if normalized_legal_moves
        else bool(
            selected_move_name
        )
    )

    return {
        "scenario_id":
            str(
                scenario_id
            ),

        "condition_id":
            str(
                condition_id
            ),

        "decision_number":
            int(
                decision_number
            ),

        "turn_number":
            int(
                getattr(
                    battle_state,
                    "turn_number",
                    0,
                )
            ),

        "acting_side":
            current_player,

        "opposing_side":
            opposing_side,

        "acting_card":
            str(
                acting_profile.get(
                    "active_card",
                    "",
                )
            ),

        "opposing_card":
            str(
                opposing_profile.get(
                    "active_card",
                    "",
                )
            ),

        "acting_hp":
            acting_profile.get(
                "hp_value",
                acting_profile.get(
                    "current_hp",
                    np.nan,
                ),
            ),

        "opposing_hp":
            opposing_profile.get(
                "hp_value",
                opposing_profile.get(
                    "current_hp",
                    np.nan,
                ),
            ),

        "acting_energy":
            acting_energy_value,

        "opposing_energy":
            opposing_energy_value,

        "acting_energy_observed":
            acting_energy_observed,

        "opposing_energy_observed":
            opposing_energy_observed,

        "legal_moves":
            normalized_legal_moves,

        "legal_move_count":
            int(
                len(
                    normalized_legal_moves
                )
            ),

        "selected_move":
            selected_move_name,

        "selected_move_is_legal":
            bool(
                selected_move_is_legal
            ),

        "routing_reason":
            str(
                routing_reason
            ),

        "confidence":
            confidence,
    }


# --------------------------------------------------------------------------------------
# 7. Instrumented runner wrapper
# --------------------------------------------------------------------------------------

class InstrumentedLegalityAwareRunner:
    """
    Non-invasive wrapper around the reconstructed Notebook 53 battle runner.

    The wrapper records state and energy evidence before returning each decision.
    """

    def __init__(
        self,
        runner: Any,
    ) -> None:

        self.runner = runner
        self.instrumentation_rows = []
        self.current_scenario_id = ""
        self.current_condition_id = ""
        self.decision_number = 0

    def configure_scenario(
        self,
        scenario_id: str,
        condition_id: str,
    ) -> None:

        self.current_scenario_id = str(
            scenario_id
        )

        self.current_condition_id = str(
            condition_id
        )

        self.decision_number = 0

    def reset(
        self,
    ) -> None:

        reset_method = getattr(
            self.runner,
            "reset",
            None,
        )

        if callable(
            reset_method
        ):

            reset_method()

        self.decision_number = 0

    def choose_move(
        self,
        state: Any,
        depth: Optional[int] = None,
    ) -> Any:

        self.decision_number += 1

        policy_agent = getattr(
            self.runner,
            "policy_agent",
            notebook54_legality_policy,
        )

        previous_history_length = (
            get_policy_history_length(
                policy_agent
            )
        )

        decision = self.runner.choose_move(
            state,
            depth=depth,
        )

        latest_history_record = (
            get_latest_policy_history_record(
                policy_agent,
                previous_history_length,
            )
        )

        selected_move_name = ensure_action_name(
            decision
        )

        if not selected_move_name:

            selected_move_name = ensure_action_name(
                get_record_field(
                    latest_history_record,
                    [
                        "selected_move",
                        "move",
                        "action",
                    ],
                    "",
                )
            )

        legal_moves = normalize_legal_move_collection(
            get_record_field(
                latest_history_record,
                [
                    "legal_moves",
                    "legal_move_names",
                    "available_moves",
                    "legal_actions",
                ],
                None,
            )
        )

        legal_move_source = (
            "POLICY_HISTORY"
            if legal_moves
            else "SELECTED_MOVE_FALLBACK"
        )

        if (
            not legal_moves
            and selected_move_name
        ):

            legal_moves = [
                selected_move_name
            ]

        routing_reason = str(
            get_record_field(
                latest_history_record,
                [
                    "routing_reason",
                    "route_reason",
                    "decision_reason",
                ],
                "",
            )
        )

        confidence_value = get_record_field(
            latest_history_record,
            [
                "confidence",
                "prediction_confidence",
                "selected_probability",
            ],
            np.nan,
        )

        try:

            confidence_value = float(
                confidence_value
            )

        except (
            TypeError,
            ValueError,
        ):

            confidence_value = np.nan

        instrumentation_record = (
            build_energy_instrumentation_record(
                battle_state=state,
                scenario_id=self.current_scenario_id,
                condition_id=self.current_condition_id,
                decision_number=self.decision_number,
                legal_moves=legal_moves,
                selected_move=selected_move_name,
                routing_reason=routing_reason,
                confidence=confidence_value,
            )
        )

        instrumentation_record[
            "legal_move_source"
        ] = legal_move_source

        instrumentation_record[
            "policy_history_record_available"
        ] = latest_history_record is not None

        instrumentation_record[
            "runner_decision_type"
        ] = type(
            decision
        ).__name__

        instrumentation_record[
            "runner_depth_argument"
        ] = (
            int(
                depth
            )
            if depth is not None
            else int(
                getattr(
                    self.runner,
                    "default_search_depth",
                    0,
                )
            )
        )

        instrumentation_record[
            "instrumentation_sequence"
        ] = int(
            len(
                self.instrumentation_rows
            )
            +
            1
        )

        self.instrumentation_rows.append(
            instrumentation_record
        )

        return decision

    def statistics(
        self,
    ) -> Dict[str, Any]:

        statistics_method = getattr(
            self.runner,
            "statistics",
            None,
        )

        runner_statistics = {}

        if callable(
            statistics_method
        ):

            try:

                runner_statistics = (
                    statistics_method()
                )

            except Exception:

                runner_statistics = {}

        if not isinstance(
            runner_statistics,
            dict,
        ):

            runner_statistics = {}

        return {
            **runner_statistics,

            "instrumented_decisions":
                int(
                    len(
                        self.instrumentation_rows
                    )
                ),
        }


