section4vb_constant_assignment_rows = []


for cell_index, notebook_cell in enumerate(
    notebook53_document.cells
):

    if notebook_cell.cell_type != "code":
        continue

    source_text = str(
        notebook_cell.source
    )

    if not source_text.strip():
        continue

    try:

        parsed_cell = ast.parse(
            source_text
        )

    except SyntaxError:
        continue

    for node in ast.walk(
        parsed_cell
    ):

        assignment_pairs = []

        if isinstance(
            node,
            ast.Assign,
        ):

            for assignment_target in node.targets:

                if isinstance(
                    assignment_target,
                    ast.Name,
                ):

                    assignment_pairs.append(
                        (
                            assignment_target.id,
                            node.value,
                        )
                    )

        elif isinstance(
            node,
            ast.AnnAssign,
        ) and isinstance(
            node.target,
            ast.Name,
        ):

            assignment_pairs.append(
                (
                    node.target.id,
                    node.value,
                )
            )

        elif isinstance(
            node,
            ast.NamedExpr,
        ) and isinstance(
            node.target,
            ast.Name,
        ):

            assignment_pairs.append(
                (
                    node.target.id,
                    node.value,
                )
            )

        for constant_name, value_node in assignment_pairs:

            if constant_name not in REQUIRED_BUILDER_CONSTANTS_4VB:
                continue

            try:

                assignment_source = ast.get_source_segment(
                    source_text,
                    node,
                )

            except Exception:

                assignment_source = None

            if not assignment_source:

                assignment_source = ast.unparse(
                    node
                )

            try:

                value_source = ast.unparse(
                    value_node
                )

            except Exception:

                value_source = ""

            literal_value = None
            literal_recovered = False

            try:

                literal_value = ast.literal_eval(
                    value_node
                )

                literal_recovered = True

            except Exception:

                pass

            section4vb_constant_assignment_rows.append(
                {
                    "constant_name":
                        constant_name,

                    "cell_index":
                        int(
                            cell_index
                        ),

                    "line_number":
                        int(
                            getattr(
                                node,
                                "lineno",
                                0,
                            )
                        ),

                    "value_source":
                        value_source,

                    "literal_value":
                        literal_value,

                    "literal_recovered":
                        bool(
                            literal_recovered
                        ),

                    "assignment_source":
                        assignment_source,
                }
            )


