# --------------------------------------------------------------------------------------
# 2. Load and evaluate each candidate
# --------------------------------------------------------------------------------------

section4vb_legal_move_candidate_profiles = []
section4vb_legal_move_candidate_objects = {}


for source_index, source_row in (
    section4vb_legal_move_sources_df.iterrows()
):

    csv_path = Path(
        source_row[
            "csv_path"
        ]
    )

    candidate_df = pd.read_csv(
        csv_path
    )

    scenario_column = str(
        source_row[
            "scenario_column"
        ]
    )

    side_column = str(
        source_row[
            "side_column"
        ]
    )

    legal_moves_column = str(
        source_row[
            "legal_moves_column"
        ]
    )

    candidate_df = candidate_df[
        [
            scenario_column,
            side_column,
            legal_moves_column,
        ]
    ].copy()

    candidate_df = candidate_df.dropna(
        subset=[
            scenario_column,
            side_column,
            legal_moves_column,
        ]
    )

    candidate_df[
        "resolved_legal_moves"
    ] = candidate_df[
        legal_moves_column
    ].map(
        parse_serialized_list
    )

    candidate_df[
        "resolved_legal_moves"
    ] = candidate_df[
        "resolved_legal_moves"
    ].map(
        lambda values: [
            str(
                value
            ).strip()
            for value in values
            if str(
                value
            ).strip()
        ]
    )

    candidate_df = candidate_df.loc[
        candidate_df[
            "resolved_legal_moves"
        ].map(
            len
        ).gt(
            0
        )
    ].copy()

    candidate_df[
        "lookup_key"
    ] = list(
        zip(
            candidate_df[
                scenario_column
            ].astype(str),
            candidate_df[
                side_column
            ].astype(str),
        )
    )

    unique_lookup_keys = int(
        candidate_df[
            "lookup_key"
        ].nunique()
    )

    covered_scenarios = int(
        candidate_df[
            scenario_column
        ].astype(str).nunique()
    )

    valid_sides = sorted(
        candidate_df[
            side_column
        ].astype(str).unique().tolist()
    )

    profile_score = (
        unique_lookup_keys * 10
        +
        covered_scenarios * 5
        +
        (
            100
            if covered_scenarios == 24
            else 0
        )
        +
        (
            50
            if set(
                valid_sides
            ).issubset(
                {
                    "Player",
                    "Opponent",
                }
            )
            else 0
        )
        +
        int(
            source_row[
                "source_priority"
            ]
        )
    )

    section4vb_legal_move_candidate_objects[
        int(
            source_index
        )
    ] = candidate_df

    section4vb_legal_move_candidate_profiles.append(
        {
            "source_index":
                int(
                    source_index
                ),

            "csv_path":
                str(
                    csv_path
                ),

            "rows":
                int(
                    len(
                        candidate_df
                    )
                ),

            "unique_lookup_keys":
                unique_lookup_keys,

            "covered_scenarios":
                covered_scenarios,

            "sides":
                valid_sides,

            "profile_score":
                int(
                    profile_score
                ),
        }
    )


