def resolve_section4wd_column(
    dataframe,
    candidates,
):
    for column_name in candidates:

        if column_name in dataframe.columns:
            return column_name

    raise KeyError(
        "Unable to resolve required column from candidates: "
        f"{candidates}"
    )


