from typing import Any, Iterable
import re

import numpy as np


# --------------------------------------------------------------------------------------
# 1. Generic state-value reader
# --------------------------------------------------------------------------------------

def get_state_value(
    source: Any,
    attribute_name: str,
    default: Any = None,
) -> Any:
    """
    Read a value from either an object attribute or dictionary key.
    """

    if source is None:
        return default

    if isinstance(source, dict):
        return source.get(
            attribute_name,
            default,
        )

    return getattr(
        source,
        attribute_name,
        default,
    )


# --------------------------------------------------------------------------------------
# 2. Card-name extraction
# --------------------------------------------------------------------------------------

def get_card_name(
    active_pokemon: Any,
) -> str:
    """
    Extract the active Pokémon/card name from the live simulator object.
    """

    if active_pokemon is None:
        return "UNKNOWN"

    direct_name = get_state_value(
        active_pokemon,
        "name",
        None,
    )

    if direct_name not in {
        None,
        "",
    }:
        return str(
            direct_name
        ).strip()

    card_value = get_state_value(
        active_pokemon,
        "card",
        None,
    )

    if isinstance(
        card_value,
        dict,
    ):
        card_name = card_value.get(
            "name",
            "UNKNOWN",
        )

    else:
        card_name = get_state_value(
            card_value,
            "name",
            "UNKNOWN",
        )

    return str(
        card_name
    ).strip() or "UNKNOWN"


# --------------------------------------------------------------------------------------
# 3. Attached-energy extraction
# --------------------------------------------------------------------------------------

def get_attached_energy(
    active_pokemon: Any,
) -> float:
    """
    Extract attached energy using the known simulator aliases.
    """

    if active_pokemon is None:
        return 0.0

    for attribute_name in [
        "attached_energy",
        "energy",
        "energy_count",
        "energies",
    ]:

        energy_value = get_state_value(
            active_pokemon,
            attribute_name,
            None,
        )

        if energy_value is None:
            continue

        if isinstance(
            energy_value,
            (
                list,
                tuple,
                set,
                dict,
            ),
        ):
            return float(
                len(
                    energy_value
                )
            )

        try:
            return float(
                energy_value
            )

        except (
            TypeError,
            ValueError,
        ):
            continue

    return 0.0


# --------------------------------------------------------------------------------------
# 4. Damage extraction
# --------------------------------------------------------------------------------------

def get_pokemon_damage(
    active_pokemon: Any,
) -> float:
    """
    Return accumulated damage.

    If only maximum/current HP are available:
        damage = maximum HP - current HP
    """

    if active_pokemon is None:
        return 0.0

    for attribute_name in [
        "damage",
        "damage_taken",
        "accumulated_damage",
    ]:

        value = get_state_value(
            active_pokemon,
            attribute_name,
            None,
        )

        if value is not None:

            try:
                return float(
                    value
                )

            except (
                TypeError,
                ValueError,
            ):
                pass

    current_hp = get_state_value(
        active_pokemon,
        "current_hp",
        None,
    )

    maximum_hp = get_state_value(
        active_pokemon,
        "max_hp",
        None,
    )

    if maximum_hp is None:
        maximum_hp = get_state_value(
            active_pokemon,
            "maximum_hp",
            None,
        )

    if current_hp is not None and maximum_hp is not None:

        try:
            return max(
                0.0,
                float(
                    maximum_hp
                )
                -
                float(
                    current_hp
                ),
            )

        except (
            TypeError,
            ValueError,
        ):
            pass

    return 0.0


# --------------------------------------------------------------------------------------
# 5. Move-name extraction
# --------------------------------------------------------------------------------------

def extract_move_name(
    move_value: Any,
) -> str:
    """
    Extract a normalized display name from a legal-move value.
    """

    if move_value is None:
        return ""

    if isinstance(
        move_value,
        str,
    ):
        return move_value.strip()

    if isinstance(
        move_value,
        dict,
    ):

        for key_name in [
            "name",
            "move_name",
            "action_name",
            "action",
            "move",
        ]:

            if key_name in move_value:

                return extract_move_name(
                    move_value[
                        key_name
                    ]
                )

    for attribute_name in [
        "name",
        "move_name",
        "action_name",
        "action",
        "move",
    ]:

        attribute_value = getattr(
            move_value,
            attribute_name,
            None,
        )

        if attribute_value is not None:

            nested_name = extract_move_name(
                attribute_value
            )

            if nested_name:
                return nested_name

    return str(
        move_value
    ).strip()


# --------------------------------------------------------------------------------------
# 6. Canonical legal-move signature
# --------------------------------------------------------------------------------------

def canonical_move_signature(
    move_values: Iterable[Any],
) -> str:
    """
    Create a deterministic legal-move signature.
    """

    move_names = [
        extract_move_name(
            move_value
        )
        for move_value in move_values
    ]

    normalized_names = sorted(
        {
            move_name.strip()
            for move_name in move_names
            if move_name.strip()
        }
    )

    return " | ".join(
        normalized_names
    )


# --------------------------------------------------------------------------------------
# 7. Turn-phase classification
# --------------------------------------------------------------------------------------

def classify_turn_phase(
    turn_number: Any,
) -> str:
    """
    Classify the battle turn into an interpretable phase.
    """

    try:
        turn_value = int(
            float(
                turn_number
            )
        )

    except (
        TypeError,
        ValueError,
    ):
        return "UNKNOWN"

    if turn_value <= 2:
        return "EARLY"

    if turn_value <= 5:
        return "EARLY_MID"

    if turn_value <= 10:
        return "MID"

    return "LATE"


# --------------------------------------------------------------------------------------
# 8. Energy-band classification
# --------------------------------------------------------------------------------------

def classify_energy_band(
    energy_value: Any,
) -> str:
    """
    Convert attached energy into a categorical band.
    """

    try:
        energy = float(
            energy_value
        )

    except (
        TypeError,
        ValueError,
    ):
        return "UNKNOWN"

    if energy <= 0:
        return "ZERO"

    if energy == 1:
        return "ONE"

    if energy == 2:
        return "TWO"

    if energy == 3:
        return "THREE"

    return "FOUR_PLUS"


# --------------------------------------------------------------------------------------
# 9. Damage-band classification
# --------------------------------------------------------------------------------------

def classify_damage_band(
    damage_value: Any,
) -> str:
    """
    Convert accumulated damage into a categorical band.
    """

    try:
        damage = float(
            damage_value
        )

    except (
        TypeError,
        ValueError,
    ):
        return "UNKNOWN"

    if damage <= 0:
        return "NONE"

    if damage < 20:
        return "LOW"

    if damage < 50:
        return "MODERATE"

    if damage < 80:
        return "HIGH"

    return "CRITICAL"


