# --------------------------------------------------------------------------------------
# 2. Restore the Notebook 53 legality-aware feature builder
# --------------------------------------------------------------------------------------

def build_legality_aware_feature_row(
    battle_state: Any,
    legal_moves: Sequence[Any],
    side_mode: str = "PRESERVE",
) -> pd.DataFrame:
    """
    Convert a production battle state into the Notebook 53 raw feature schema.
    """

    current_side = str(
        get_state_value(
            battle_state,
            "current_player",
            "Player",
        )
    )

    player_state = get_state_value(
        battle_state,
        "player",
    )

    opponent_state = get_state_value(
        battle_state,
        "opponent",
    )

    player_active = get_state_value(
        player_state,
        "active",
    )

    opponent_active = get_state_value(
        opponent_state,
        "active",
    )

    player_card = get_card_name(
        player_active
    )

    opponent_card = get_card_name(
        opponent_active
    )

    player_energy = get_attached_energy(
        player_active
    )

    opponent_energy = get_attached_energy(
        opponent_active
    )

    player_damage = get_pokemon_damage(
        player_active
    )

    opponent_damage = get_pokemon_damage(
        opponent_active
    )

    acting_is_player = (
        current_side.strip().lower()
        ==
        "player"
    )

    active_card = (
        player_card
        if acting_is_player
        else opponent_card
    )

    inactive_card = (
        opponent_card
        if acting_is_player
        else player_card
    )

    acting_energy = (
        player_energy
        if acting_is_player
        else opponent_energy
    )

    defending_energy = (
        opponent_energy
        if acting_is_player
        else player_energy
    )

    acting_damage = (
        player_damage
        if acting_is_player
        else opponent_damage
    )

    defending_damage = (
        opponent_damage
        if acting_is_player
        else player_damage
    )

    legal_move_names = [
        extract_move_name(
            move
        )
        for move in legal_moves
    ]

    normalized_legal_moves = [
        normalize_action_name(
            move_name
        )
        for move_name in legal_move_names
    ]

    legal_move_count = len(
        legal_move_names
    )

    feature_row = {
        "turn_number":
            float(
                get_state_value(
                    battle_state,
                    "turn_number",
                    1,
                )
            ),

        "player_energy":
            player_energy,

        "opponent_energy":
            opponent_energy,

        "player_damage":
            player_damage,

        "opponent_damage":
            opponent_damage,

        "prize_cards_remaining":
            float(
                get_state_value(
                    player_state,
                    "prize_cards_remaining",
                    6,
                )
            ),

        "hand_size":
            float(
                get_state_value(
                    player_state,
                    "hand_size",
                    7,
                )
            ),

        "recomputed_legal_move_count":
            float(
                legal_move_count
            ),

        "acting_energy":
            acting_energy,

        "defending_energy":
            defending_energy,

        "energy_difference":
            acting_energy
            -
            defending_energy,

        "absolute_energy_difference":
            abs(
                acting_energy
                -
                defending_energy
            ),

        "acting_damage":
            acting_damage,

        "defending_damage":
            defending_damage,

        "damage_difference":
            acting_damage
            -
            defending_damage,

        "absolute_damage_difference":
            abs(
                acting_damage
                -
                defending_damage
            ),

        "single_legal_move_flag":
            int(
                legal_move_count == 1
            ),

        "multi_legal_move_flag":
            int(
                legal_move_count > 1
            ),

        "model_choice_required_flag":
            int(
                legal_move_count > 1
            ),

        "current_side":
            current_side,

        "side_mode":
            str(
                side_mode
            ),

        "player_card":
            player_card,

        "opponent_card":
            opponent_card,

        "active_card":
            active_card,

        "inactive_card":
            inactive_card,

        "legal_move_signature":
            canonical_move_signature(
                legal_move_names
            ),

        "battle_phase":
            classify_turn_phase(
                get_state_value(
                    battle_state,
                    "turn_number",
                    1,
                )
            ),

        "energy_band":
            classify_energy_band(
                acting_energy
            ),

        "damage_band":
            classify_damage_band(
                acting_damage
            ),
    }

    for action_name in POLICY_ACTION_CLASSES:

        normalized_action = normalize_action_name(
            action_name
        )

        legal_flag_column = (
            "is_legal__"
            +
            action_feature_name(
                action_name
            )
        )

        compatibility_column = (
            "active_card_can_use__"
            +
            action_feature_name(
                action_name
            )
        )

        feature_row[
            legal_flag_column
        ] = int(
            normalized_action
            in normalized_legal_moves
        )

        feature_row[
            compatibility_column
        ] = int(
            normalized_action
            in training_active_card_action_map.get(
                active_card,
                [],
            )
        )

    feature_dataframe = pd.DataFrame(
        [
            feature_row
        ]
    )

    for column_name in (
        legality_training_numeric_features
    ):

        feature_dataframe[
            column_name
        ] = pd.to_numeric(
            feature_dataframe[
                column_name
            ],
            errors="coerce",
        ).fillna(
            0.0
        ).astype(
            float
        )

    for column_name in (
        legality_training_categorical_features
    ):

        feature_dataframe[
            column_name
        ] = (
            feature_dataframe[
                column_name
            ]
            .fillna(
                "UNKNOWN"
            )
            .astype(str)
        )

    feature_dataframe = feature_dataframe[
        PREPROCESS_RAW_FEATURES
    ]

    assert feature_dataframe.shape == (
        1,
        41,
    ), (
        "Unexpected raw feature shape: "
        f"{feature_dataframe.shape}; expected (1, 41)."
    )

    return feature_dataframe


