section4whb_label_inventory_df = (
    section4wh_training_label_inventory_df
    .copy()
    .reset_index(drop=True)
)


if not section4whb_label_inventory_df.empty:

    section4whb_label_inventory_df[
        "target_label_rows"
    ] = (
        section4whb_label_inventory_df[
            "quick_attack_rows"
        ]
        +
        section4whb_label_inventory_df[
            "ascension_rows"
        ]
    )


    section4whb_label_inventory_df[
        "quick_attack_target_share"
    ] = np.where(
        section4whb_label_inventory_df[
            "target_label_rows"
        ] > 0,

        section4whb_label_inventory_df[
            "quick_attack_rows"
        ]
        /
        section4whb_label_inventory_df[
            "target_label_rows"
        ],

        np.nan,
    )


    section4whb_label_inventory_df[
        "ascension_target_share"
    ] = np.where(
        section4whb_label_inventory_df[
            "target_label_rows"
        ] > 0,

        section4whb_label_inventory_df[
            "ascension_rows"
        ]
        /
        section4whb_label_inventory_df[
            "target_label_rows"
        ],

        np.nan,
    )


    section4whb_label_inventory_df = (
        section4whb_label_inventory_df
        .sort_values(
            [
                "target_label_rows",
                "dataframe_name",
            ],
            ascending=[
                False,
                True,
            ],
        )
        .reset_index(drop=True)
    )


