# --------------------------------------------------------------------------------------
# 6. Helpers for modifying one reconstructed state
# --------------------------------------------------------------------------------------

def get_section4whe_active_pokemon(
    battle_state,
    evaluation_side,
):
    evaluation_side = str(
        evaluation_side
    ).strip().title()


    side_state = (
        getattr(
            battle_state,
            "player",
        )
        if evaluation_side == "Player"
        else
        getattr(
            battle_state,
            "opponent",
        )
    )


    return getattr(
        side_state,
        "active",
    )


def get_section4whe_opposing_pokemon(
    battle_state,
    evaluation_side,
):
    evaluation_side = str(
        evaluation_side
    ).strip().title()


    side_state = (
        getattr(
            battle_state,
            "opponent",
        )
        if evaluation_side == "Player"
        else
        getattr(
            battle_state,
            "player",
        )
    )


    return getattr(
        side_state,
        "active",
    )


def apply_section4whe_state_counterfactual(
    evaluation_state,
    design_row,
    counterfactual,
):
    """
    Apply energy and turn changes directly to one copied evaluation state.
    """

    evaluation_side = str(
        design_row[
            "evaluation_side"
        ]
    ).strip().title()


    acting_active = get_section4whe_active_pokemon(
        evaluation_state,
        evaluation_side,
    )


    opposing_active = get_section4whe_opposing_pokemon(
        evaluation_state,
        evaluation_side,
    )


    acting_energy_mode = counterfactual[
        "acting_energy"
    ]


    opposing_energy_mode = counterfactual[
        "opposing_energy"
    ]


    turn_mode = counterfactual[
        "turn_number"
    ]


    if acting_energy_mode != "SOURCE":

        setattr(
            acting_active,
            "attached_energy",
            int(
                float(
                    acting_energy_mode
                )
            ),
        )


    if opposing_energy_mode != "SOURCE":

        setattr(
            opposing_active,
            "attached_energy",
            int(
                float(
                    opposing_energy_mode
                )
            ),
        )


    if turn_mode != "SOURCE":

        setattr(
            evaluation_state,
            "turn_number",
            int(
                turn_mode
            ),
        )


    return evaluation_state


